import re
from typing import Tuple, List, Union, Any

# Regex derived from SemVer 2.0.0 specification.
# Captures: MAJOR, MINOR, PATCH, PRERELEASE, BUILD
# Major, Minor, Patch: (0|[1-9]\d*) enforces no leading zeros unless it's just '0'.
# Identifiers: (?:[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)

# Full pattern: ^(MAJOR)\.(MINOR)\.(PATCH)(?:-PRERELEASE)?(?:\+BUILD)?$
SEMVER_REGEX = re.compile(
    r'^(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)'  # MAJOR.MINOR.PATCH
    r'(?:-(?P<prerelease>(?:0|[1-9]\d*|[a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)))?'  # Optional pre-release
    r'(?:\+(?P<build>[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'  # Optional build metadata
)

def _parse_identifiers(identifiers_str: str) -> Tuple[str, ...]:
    """Parses a dot-separated list of SemVer identifiers."""
    if not identifiers_str:  # Should not happen if regex is correct, but for safety
        return tuple()
    return tuple(identifiers_str.split('.'))

class Version:
    """Represents a Semantic Versioning 2.0.0 compliant version number."""

    def __init__(self, major: int, minor: int, patch: int,
                 prerelease: Tuple[str, ...], build: Tuple[str, ...]):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    @staticmethod
    def _validate_identifier(identifier: str, is_numeric: bool) -> None:
        """Validates a single SemVer identifier."""
        if not identifier: # Should be caught by regex structure, but explicit check for robustness
            raise ValueError("Version identifier cannot be empty.")
        if is_numeric and identifier.startswith('0') and len(identifier) > 1:
            # Numeric identifiers MUST NOT have leading zeros unless they are '0'
            raise ValueError("Numeric identifier cannot have leading zeros.")

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """Parses a full version string into a Version object, validating against SemVer 2.0.0.

        Raises ValueError for malformed input, leading 'v', whitespace, or missing parts.
        """
        if not text or text.startswith('v') or re.search(r'\s', text):
            raise ValueError("Invalid version string format: must not start with 'v' or contain whitespace.")

        match = SEMVER_REGEX.match(text)
        if not match:
            raise ValueError(f"Invalid SemVer 2.0.0 format: {text}")

        data = match.groupdict()

        major = int(data['major'])
        minor = int(data['minor'])
        patch = int(data['patch'])

        prerelease = tuple()
        build = tuple()

        if data['prerelease']:  # Pre-release section present
            prerelease_parts = _parse_identifiers(data['prerelease'])
            for part in prerelease_parts:
                try:
                    # Check if the identifier is purely numeric
                    if part.isdigit():
                        # Numeric identifiers must not have leading zeros unless '0'
                        if len(part) > 1 and part.startswith('0'):
                            raise ValueError
                        # Cast to int for internal check, but keep as string for tuple storage
                        pass
                    # Alphanumeric/hyphen identifiers are fine as long as they aren't empty
                except ValueError as e:
                    raise ValueError(f"Invalid pre-release identifier '{part}': {e}") from e
            prerelease = tuple(prerelease_parts)

        if data['build']:  # Build metadata present
            build_parts = _parse_identifiers(data['build'])
            # Build identifiers can be numeric with leading zeros
            build = tuple(build_parts)

        # Final check: Ensure the original text matches the canonical form derived from components
        # (This is implicitly handled by SEMVER_REGEX matching the whole string, but good practice)
        # We trust the regex for structural validity based on SemVer spec.

        return cls(major, minor, patch, prerelease, build)

    def __str__(self) -> str:
        """Returns the canonical text from which the version was parsed (reconstructed here)."""
        # Since we are not storing the original text, we reconstruct it based on components.
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += f"-{'.'.join(self.prerelease)}"
        if self.build:
            s += f"+{'.'.join(self.build)}"
        return s

    # --- Comparison Operators ---

    def _compare_precedence(self, other: 'Version') -> int:  # Returns -1, 0, 1
        """Compares two Version objects based on SemVer precedence. Ignores build metadata."""
        # 1. Compare Major, Minor, Patch numerically
        v_parts = [self.major, self.minor, self.patch]
        o_parts = [other.major, other.minor, other.patch]

        for v, o in zip(v_parts, o_parts):
            if v < o: return -1
            if v > o: return 1

        # M.m.p are equal. Now check pre-release.
        self_has_prerelease = bool(self.prerelease)
        other_has_prerelease = bool(other.prerelease)

        if not self_has_prerelease and other_has_prerelease:
            return 1  # Stable > Pre-release
        if self_has_prerelease and not other_has_prerelease:
            return -1 # Pre-release < Stable
        if not self_has_prerelease and not other_has_prerelease:
            return 0  # Both stable

        # Both have pre-release. Compare identifiers.
        for self_id, other_id in zip(self.prerelease, other.prerelease):
            # Numeric identifiers are compared numerically; alphanumeric in ASCII order.
            is_self_numeric = self_id.isdigit()
            is_other_numeric = other_id.isdigit()

            if is_self_numeric and is_other_numeric:
                s_val = int(self_id)
                o_val = int(other_id)
                if s_val < o_val: return -1
                if s_val > o_val: return 1
                # Equal, continue to next identifier
            elif is_self_numeric and not is_other_numeric:
                # Numeric < Alphanumeric (as per standard)
                return -1
            elif not is_self_numeric and is_other_numeric:
                # Alphanumeric > Numeric
                return 1
            else: # Both are alphanumeric or mixed string identifiers
                if self_id < other_id: return -1
                if self_id > other_id: return 1
                # Equal, continue to next identifier

        # If all identifiers are equal, the shorter list is lower (if one is a prefix of the other).
        if len(self.prerelease) < len(other.prerelease): return -1
        if len(self.prerelease) > len(other.prerelease): return 1

        return 0

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        # Equality ignores build metadata
        return (self.major == other.major and self.minor == other.minor and self.patch == other.patch and 
                self.prerelease == other.prerelease)

    def __lt__(self, other: Any) -> bool:
        return self._compare_precedence(other) == -1

    def __le__(self, other: Any) -> bool:
        return self._compare_precedence(other) <= 0

    def __gt__(self, other: Any) -> bool:
        return self._compare_precedence(other) == 1

    def __ge__(self, other: Any) -> bool:
        return self._compare_precedence(other) >= 0

    def __ne__(self, other: Any) -> bool:
        return self not in (other, other.__ne__(self))

    def __hash__(self) -> int:
        # Hash must agree with equality (ignoring build metadata)
        return hash((self.major, self.minor, self.patch, self.prerelease))

    # --- Version Bumping ---

    def bump(self, kind: str) -> 'Version':
        """Returns a new version bumped according to the specified kind ('major', 'minor', 'patch').
        The resulting version always has no pre-release or build metadata.
        """
        if kind not in ('major', 'minor', 'patch'):
            raise ValueError(f"Invalid bump kind: {kind}. Must be 'major', 'minor', or 'patch'.")

        if kind == 'major':
            new_version = Version(self.major + 1, 0, 0, tuple(), tuple())
        elif kind == 'minor':
            new_version = Version(self.major, self.minor + 1, 0, tuple(), tuple())
        elif kind == 'patch':
            new_version = Version(self.major, self.minor, self.patch + 1, tuple(), tuple())

        return new_version

# =============================================================================
# Version Range Satisfies Check
# =============================================================================

# Helper to parse partial versions from spec strings (e.g., '1', '1.2')
def _parse_partial_version(partial_text: str) -> Version:
    """Parses a partial version string (e.g., '1' or '1.2') into a canonical Version object (e.g., 1.0.0 or 1.2.0)."""
    parts = [int(p) for p in partial_text.split('.')]

    major = parts[0] if len(parts) > 0 else 0
    minor = parts[1] if len(parts) > 1 else 0
    patch = parts[2] if len(parts) > 2 else 0

    # Partial versions cannot have pre-release or build parts per spec
    return Version(major, minor, patch, tuple(), tuple())

# Helper to parse a comparator (e.g., '^1.2.3', '~1.2', '>=2.0')
def _parse_comparator(comparator: str) -> Tuple[str, Union[Version, None]]:
    """Parses a comparator string into (operator, base_version)."""
    comparator = comparator.strip()

    if comparator.startswith('^'):
        op = '^'
        base_str = comparator[1:].strip()
    elif comparator.startswith('~'):
        op = '~'
        base_str = comparator[1:].strip()
    elif comparator.startswith(('>=', '>', '<=', '<', '=')): 
        # Determine operator length (1 or 2 chars)
        if comparator.startswith(('>=', '<=', '==')): # Although '==' is not standard for range, we check for 2-char operators
            op = comparator[:2]
        elif comparator.startswith(('>', '<')): 
            op = comparator[:1]
        else:
            op = '=' # Should be caught above if '=' is used alone

        # Refined operator parsing for robustness
        if comparator.startswith('>='): op = '>=' ; base_str = comparator[2:].strip()
        elif comparator.startswith('<='): op = '<=' ; base_str = comparator[2:].strip()
        elif comparator.startswith('>'): op = '>' ; base_str = comparator[1:].strip()
        elif comparator.startswith('<'): op = '<' ; base_str = comparator[1:].strip()
        elif comparator.startswith('='): op = '=' ; base_str = comparator[1:].strip()
        else: raise ValueError(f"Could not parse operator in {comparator}")

    else:
        # Bare version comparison, implicitly '=' operator
        op = '=' 
        base_str = comparator

    if not base_str:
         raise ValueError(f"Malformed comparator: {comparator}")

    # Parse the base version. Since this is for comparison, we use the partial parser.
    try:
        base_version = _parse_partial_version(base_str)
    except ValueError as e:
        raise ValueError(f"Invalid base version in comparator '{base_str}': {e}") from e

    return op, base_version

# Main function for satisfying versions
def satisfies(version: Version, spec: str) -> bool:
    """Checks if a given version satisfies all comparators in the specification string.
    """
    if not spec or not spec.strip():
        raise ValueError("Specification string cannot be empty.")

    comparators = spec.split()

    for comparator_str in comparators:
        try:
            op, base_v = _parse_comparator(comparator_str)
        except ValueError as e:
            raise ValueError(f"Invalid comparator '{comparator_str}' in spec '{spec}': {e}") from e

        # 1. Handle standard relational operators
        if op == '=': # Bare V or =V
            if version != base_v:
                return False
        elif op == '>=':
            if not version >= base_v:
                return False
        elif op == '>':
            if not version > base_v:
                return False
        elif op == '<=':
            if not version <= base_v:
                return False
        elif op == '<':
            if not version < base_v:
                return False

        # 2. Handle prefix operators (^ and ~)
        elif op == '^':
            # ^V: >=V AND < Next Major Increment
            if base_v.major == 0 and base_v.minor == 0 and base_v.patch == 0:
                # ^0.0.0 -> <0.0.1
                upper_bound = Version(0, 0, 1, tuple(), tuple())
            elif base_v.major == 0 and base_v.minor == 0:
                # ^0.X.Y -> <0.(X+1).0
                upper_bound = Version(0, base_v.minor + 1, 0, tuple(), tuple())
            else:
                # ^X.Y.Z -> <(X+1).0.0
                upper_bound = Version(base_v.major + 1, 0, 0, tuple(), tuple())

            # Check lower bound (>= base_v) and upper bound (< upper_bound)
            if not (version >= base_v and version < upper_bound):
                return False

        elif op == '~':
            # ~V: >=V AND < Next Minor Increment
            # Examples: ~1.2.3 is >=1.2.3 <1.3.0, ~1.2 is >=1.2.0 <1.3.0, ~1 is >=1.0.0 <2.0.0
            if base_v.major == 0 and base_v.minor == 0 and base_v.patch == 0:
                 # ~0.0.0 -> <0.0.1
                 upper_bound = Version(0, 0, 1, tuple(), tuple())
            elif base_v.major == 0 and base_v.minor == 0:
                 # ~0.X.Y -> <0.(X+1).0
                 upper_bound = Version(0, base_v.minor + 1, 0, tuple(), tuple())
            elif base_v.minor == 0 and base_v.patch == 0:
                 # ~X.0.0 -> <X.1.0
                 upper_bound = Version(base_v.major, 1, 0, tuple(), tuple())
            else:
                 # X.Y.Z -> <X.(Y+1).0
                 upper_bound = Version(base_v.major, base_v.minor + 1, 0, tuple(), tuple())

            if not (version >= base_v and version < upper_bound):
                return False

    return True

