## PathError Class

class PathError(LookupError):
    """Custom exception raised for path errors in jpath."""
    def __init__(self, path: str, message: str = None):
        self.path = path
        if message:
            super().__init__(f"PathError on path '{path}': {message}")
        else:
            super().__init__(f"PathError on path '{path}'")

def parse(path: str) -> list[str | int]:
    """Parses a path string into a list of segments (names or indices)."""
    if not path: 
        return []

    segments: List[Union[str, int]] = []
    i = 0
    n = len(path)

    while i < n:
        # 1. Try to parse a bare name segment
        start_name = i
        while i < n and path[i] not in ['.', '[', '"']:
            i += 1
        name = path[start_name:i]

        if name: # Successfully read a name
            segments.append(name)

            # Check what follows the name
            if i < n and path[i] == '.':
                i += 1 # Consume '.'
                continue # Move to next segment
            elif i < n and path[i] == '[':
                # Transition from name to index/quoted segment
                i += 1 # Consume '['
                if path[i] == '"':
                    # Quoted segment started, let the quoted logic handle it
                    # We must step back to let the quoted logic re-evaluate 'i'
                    i -= 1 
                    break
                else:
                    # Index segment started (e.g., a[0])
                    j = i
                    # Check for integer content
                    while j < n and path[j].isdigit() or (j == 0 and path[j] == '-'):
                        j += 1

                    if j == i: # No digits found, invalid syntax
                        raise PathError(path, f"Invalid index format after name at position {i}")

                    index_str = path[i:j]
                    try:
                        segments.append(int(index_str))
                    except ValueError:
                         # Should be caught by digit check, but as a safeguard
                        raise PathError(path, f"Invalid index value: {index_str}")

                    i = j # Advance i past the index
                    # Check what follows the index segment
                    if i < n and path[i] == ']':
                        i += 1 # Consume ']'
                        continue # Move to next segment
                    elif i < n and path[i] == '.':
                        i += 1 # Consume '.'
                        continue # Move to next segment
                    elif i < n and path[i] == '[':
                        # Consecutive index/segment: a[0][1]
                        continue
                    else:
                        # Index not followed by ']' or '.' or '[' (e.g., 'a[0]b')
                        raise PathError(path, f"Index segment at position {i-len(index_str)} not correctly terminated.")

        # 2. Handle Quoted segment (must start with '"')
        elif i < n and path[i] == '"':
            i += 1 # Consume opening '"'
            start_quoted = i
            quoted_content = []

            while i < n:
                if path[i] == '\': # Handle escape sequences
                    i += 1
                    if i >= n: raise PathError(path, "Unclosed escape sequence at end of path.")
                    if path[i] == '"':
                        quoted_content.append('"')
                    elif path[i] == '\':
                        quoted_content.append('\')
                    else:
                        # Any other backslash is an error per spec
                        raise PathError(path, f"Invalid escape sequence: \{path[i]} in quoted key.")
                elif path[i] == '"': # Closing quote
                    i += 1 # Consume closing '"'
                    segments.append("" .join(quoted_content))
                    # Check what follows the quoted segment
                    if i < n and path[i] == ']':
                        i += 1 # Consume ']'
                        continue # Move to next segment
                    elif i < n and path[i] == '.':
                        i += 1 # Consume '.'
                        continue # Move to next segment
                    elif i < n and path[i] == '[':
                        # Consecutive quoted segment followed by bracket: a["x.y" ][1]
                        continue
                    else:
                        raise PathError(path, f"Quoted segment at position {start_quoted-1} not correctly terminated.")
                else:
                    quoted_content.append(path[i])
                    i += 1

            # If loop finished without finding closing quote
            raise PathError(path, "Unclosed quoted key.")

        # 3. Handle other invalid starts
        else:
            if i < n: 
                # This covers cases like '..' or starting with '.' or ']' or '[]'
                raise PathError(path, f"Unexpected character '{path[i]}' at position {i}. Invalid path syntax.")
            break

    # Final check for trailing characters/unconsumed path elements
    if i < n: 
        # This case should ideally be caught inside the loop for structure violations
        raise PathError(path, f"Parsing failed to consume entire path string. Leftover characters starting at position {i}.")

    return segments

def get(obj: Any, path: str, default: Any = <none>) -> Any:
    """Follows the path from obj and returns the value it reaches.

    For a `str` segment, looks up that key in a `collections.abc.Mapping`.
    For an `int` segment, indexes a `list` or `tuple`.
    Any other combination counts as a missing value.

    Returns `default` if a default was passed, otherwise raises `PathError`.

    :param obj: The object to traverse.
    :param path: The path string to follow.
    :param default: The value to return on missing lookup.
    :raises PathError: If the path is syntactically invalid or a lookup fails and no default is provided.
    :return: The value found at the specified path.
    """
    try:
        segments = parse(path)
    except PathError as e:
        # Syntax error always raises PathError, even if default is provided
        raise e

    current_obj = obj
    for segment in segments:
        try:
            if isinstance(segment, str):
                # String segment: looks up key in Mapping
                if not isinstance(current_obj, collections.abc.Mapping):
                    raise TypeError("Expected a Mapping object for string segment lookup.")
                current_obj = current_obj[segment]
            elif isinstance(segment, int):
                # Integer segment: indexes List/Tuple
                if not isinstance(current_obj, (list, tuple)):
                    raise TypeError("Expected a List or Tuple object for integer segment indexing.")
                current_obj = current_obj[segment]
            else:
                # Should not happen if parse() is correct
                raise TypeError(f"Invalid segment type encountered: {type(segment).__name__}.")
        except (KeyError, IndexError, TypeError) as e:
            # Lookup failed (missing key, out-of-range index, or wrong type combination)
            if default is not <none>:
                return default

            # If no default provided, raise PathError
            raise PathError(path, f"Lookup failed at segment {segment}: {e}")

    return current_obj

