import collections.abc
from typing import Any, List, Union

class PathError(LookupError):
    """Custom exception raised for path-related errors."""
    def __init__(self, path: str, message: str = None):
        self.path = path
        if message:
            super().__init__(f"PathError: {message} for path '{path}'")
        else:
            super().__init__(f"PathError: Invalid or missing path segment for path '{path}'")


def parse(path: str) -> List[Union[str, int]]:
    """
    Parses a path string into a list of segments (strings or integers).
    Raises PathError on syntax error.
    """
    if not path: 
        return []

    segments: List[Union[str, int]] = []
    i = 0
    n = len(path)

    while i < n:
        # 1. Handle quoted key "..." 
        if path[i] == '"':
            i += 1  # Skip opening quote
            start = i
            while i < n:
                if path[i] == '\':
                    i += 1
