import collections
from typing import Callable, Any, List, Tuple, Dict, Hashable

class EmitError(Exception):
    """Custom exception raised when listeners fail during event emission."""
    def __init__(self, errors: List[Tuple[Callable, Exception]]):
        self.errors = errors
        super().__init__(f"Event emission failed for {len(errors)} listeners.")

class Emitter:
    """A synchronous event emitter."""
    def __init__(self):
        # Stores registrations: {event: list of (registration_id, listener, is_once)} 
        self._listeners: Dict[Hashable, List[Tuple[str, Callable, bool]]] = collections.defaultdict(list)
        self._next_reg_id = 0

    def on(self, event: Hashable, listener: Callable) -> Callable: 
        """Registers a listener for an event."""
        reg_id = str(self._next_reg_id)
        self._next_reg_id += 1
        # is_once = False
        self._listeners[event].append((reg_id, listener, False))
        return listener

    def once(self, event: Hashable, listener: Callable) -> Callable: 
        """Registers a listener that runs only once."""
        reg_id = str(self._next_reg_id)
        self._next_reg_id += 1
        # is_once = True
        self._listeners[event].append((reg_id, listener, True))
        return listener

    def off(self, event: Hashable, listener: Callable = None) -> int:
        """Removes a listener registration for an event."""
        removed_count = 0
        if listener is None: 
            # Remove all registrations for this event
            if event in self._listeners:
                removed_count = len(self._listeners[event])
                del self._listeners[event]
        else:
            # Remove the earliest registration of the specific listener
            try:
                # Iterate to find the first matching registration
                for i, (reg_id, l, is_once) in enumerate(self._listeners[event]):
                    if l == listener:
                        # Remove and break
                        self._listeners[event].pop(i)
                        removed_count = 1
                        break
            except KeyError:
                # Event not found
                pass
        return removed_count

    def emit(self, event: Hashable, *args, **kwargs) -> int:
        """Calls listeners registered for an event in registration order."""
        # Fixed set of listeners for this emission cycle
        # We use a copy to ensure listeners registered/removed during emission are handled correctly
        listeners_snapshot = self._listeners.get(event, [])

        # Keep track of calls and errors
        calls_made = 0
        errors_caught: List[Tuple[Callable, Exception]] = []

        # Temporary list to track registrations to remove if 'once' listener is called
        to_remove_ids = []

        for reg_id, listener, is_once in listeners_snapshot:
            try:
                listener(*args, **kwargs)
                calls_made += 1
                if is_once:
                    to_remove_ids.append(reg_id)
            except Exception as e:
                calls_made += 1  # The call still counts as made
                errors_caught.append((listener, e))

        # Clean up 'once' registrations after emission finishes
        if event in self._listeners:
            new_listeners = []
            for reg_id, l, is_once in self._listeners[event]:
                if reg_id not in to_remove_ids: 
                    new_listeners.append((reg_id, l, is_once))
            self._listeners[event] = new_listeners

        if errors_caught: 
            raise EmitError(errors_caught)

        return calls_made

    def listeners(self, event: Hashable) -> List[Callable]:
        """Returns a list of registered listeners for an event in order."""
        if event not in self._listeners:
            return []
        # Return only the listener callables from the list
        return [listener for _, listener, _ in self._listeners[event]]

from typing import Mapping, List

class TemplateError(ValueError):
    """Raised when a template syntax error is detected."""
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position

class MissingKey(KeyError):
    """Raised by render when a placeholder references a missing key without a default."""
    def __init__(self, name: str):
        super().__init__(f"Missing key: '{name}'")
        self.name = name


def _parse_placeholder(template: str, start_index: int) -> tuple[str, str | None, int]:
    """Parses a single placeholder: {name} or {name:default}

    Returns: (placeholder_name, default_value, end_index_after_closing_bracket)
    Raises: TemplateError for malformed names or missing closing brace.
    """
    i = start_index + 1
    name_start = i

    # 1. Parse Name
    name_chars = []
    while i < len(template) and (template[i].isalnum() or template[i] == '_'):
        name_chars.append(template[i])
        i += 1
    name = "".join(name_chars)

    if not name:
        raise TemplateError("Empty placeholder name", start_index)

    # 2. Check for default syntax :default}
    default_value: str | None = None
    has_default = False
    if i < len(template) and template[i] == ':' and template[i+1] != '}':
        has_default = True
        i += 1  # Skip ':'
        default_start = i

        # Default value ends at '}'
        default_end = template.find('}', i)

        if default_end == -1:
            raise TemplateError("Unclosed default value", i)

        default_value = template[default_start:default_end].strip()
        i = default_end + 1 # Move index past '}'

    # 3. Check for closing brace '}'
    if i >= len(template) or template[i] != '}':
        raise TemplateError("Missing closing brace for placeholder", start_index)

    return name, default_value, i + 1

def placeholders(template: str) -> List[str]:
    """Returns the placeholder names in order of first appearance, each once."""
    seen_names = set()
    names_in_order: List[str] = []
    i = 0
    n = len(template)

    while i < n:
        if template[i] == '{':
            # Check for escaped brace {{ -> literal {
            if i + 1 < n and template[i+1] == '{':
                i += 2
                continue

            # Potential start of placeholder
            try:
                name, _, end_index = _parse_placeholder(template, i)
            except TemplateError as e:
                # Re-raise, as per requirement: malformed template raises TemplateError immediately
                raise e

            if name not in seen_names:
                names_in_order.append(name)
                seen_names.add(name)

            i = end_index
            continue

        # Handle escaped brace }} -> literal }
        if template[i] == '}' and i + 1 < n and template[i+1] == '}':
            i += 2
            continue

        i += 1

    return names_in_order

def render(template: str, values: Mapping[str, object]) -> str:
    """Replaces each placeholder in the template with its corresponding value from values.
    """
    result = []
    i = 0
    n = len(template)

    while i < n:
        if template[i] == '{':
            # Check for escaped brace {{ -> literal {
            if i + 1 < n and template[i+1] == '{':
                result.append('{')
                i += 2
                continue

            # Potential start of placeholder
            try:
                name, default_value, end_index = _parse_placeholder(template, i)
            except TemplateError as e:
                # Per requirements: check entire syntax first
                raise e

            # Substitution logic
            if name in values:
                # Value exists, use its string representation
                result.append(str(values[name]))
            elif default_value is not None:
                # Value missing, but default exists
                result.append(str(default_value))
            else:
                # Value missing, no default exists -> Raise MissingKey
                raise MissingKey(name)

            i = end_index
            continue

        elif template[i] == '}':
            # Check for escaped brace }} -> literal }
            if i + 1 < n and template[i+1] == '}':
                result.append('}')
                i += 2
                continue
            else:
                # Unmatched single '}'
                raise TemplateError("Unexpected closing brace", i)

        # Regular character
        result.append(template[i])
        i += 1

    return "".join(result)

