from dataclasses import dataclass

class SQLError(Exception):
    """Base exception for MiniSQL errors."""
    pass

class SQLSyntaxError(SQLError):
    """Raised when the SQL statement is syntactically incorrect."""
    def __init__(self, message: str, pos: int):
        super().__init__(message)
        self.pos = pos

@dataclass(frozen=True)
@dataclass(frozen=True)
class Token:
    """Represents a token in the SQL stream."""
    kind: str
    value: str | None
    pos: int

KEYWORD_SET = { 
    "SELECT", "FROM", "WHERE", "AND", "OR", "NOT", "ORDER BY", "ASC", "DESC", "LIMIT", "IS", "NULL", "TRUE", "FALSE" 
}

OPERATOR_SET = { 
    "=", "!=", "<>", "<", "<=", ">", ">=" 
}

def tokenize(sql: str) -> list[Token]:
    """Tokenizes an SQL string into a list of Token objects."""
    tokens: list[Token] = []
    i = 0
    n = len(sql)

    while i < n:
        char = sql[i]

        # Skip whitespace
        if char.isspace():
            i += 1
            continue

        # Handle strings (single quotes)
        if char == "'" and (i + 1 < n and sql[i+1] != "\"\"" or i == 0):
            start_pos = i
            i += 1
            value = ""
            while i < n:
                if sql[i] == "'" and (i > 0 and sql[i-1] == "'" and i-2 >= 0 and sql[i-2] == "'"):
                    # Escaped quote: '' becomes ' in value
                    value += "'"
                    i += 1
                    continue
                elif sql[i] == "'" and (i == 0 or sql[i-1] != "'" or i-2 < 0 or sql[i-2] != "'"):
                    # Unescaped closing quote
                    return_val = value
                    # We need to handle the fact that the token starts at the first quote
                    tokens.append(Token("STRING", return_val, start_pos))
                    i += 1
                    break
                else:
                    value += sql[i]
                    i += 1
            else:
                # Unterminated string
                raise SQLSyntaxError("Unterminated string starting at position " + str(start_pos), start_pos)

        # Handle identifiers and keywords
        elif char.isalpha() or char == "_":
            start_pos = i
            while i < n and (sql[i].isalnum() or sql[i] == "_"):
                i += 1
            lexeme = sql[start_pos:i]
            upper_lexeme = lexeme.upper()

            if upper_lexeme in KEYWORD_SET:
                tokens.append(Token("KEYWORD", upper_lexeme, start_pos))
            else:
                tokens.append(Token("IDENT", lexeme, start_pos))

        # Handle numbers (integers and floats, possibly negative)
        elif char.isdigit() or (char == "-" and i + 1 < n and sql[i+1].isdigit()):
            start_pos = i
            is_float = False
            if char == "-":
                i += 1 # Move past '-' to start parsing number

            while i < n and (sql[i].isdigit() or sql[i] == "."):
                if sql[i] == ".":
                    if is_float: # Second dot found
                         raise SQLSyntaxError("Multiple dots in number at pos " + str(i), i)
                    is_float = True
                i += 1

            lexeme = sql[start_pos:i]
            try:
                if is_float:
                    value = float(lexeme)
                else:
                    value = int(lexeme)
            except ValueError:
                raise SQLSyntaxError(f"Invalid number format '{lexeme}' at pos {start_pos}", start_pos)

            tokens.append(Token("NUMBER", value, start_pos))

        # Handle operators and punctuation
        elif char in ":,()*":
            pos = i
            if char == "*":
                tokens.append(Token("STAR", "*", pos))
            elif char == "-":
                # Negative sign handled by number parsing unless it's part of a comparison operator
                # We rely on the number parsing above to catch negative numbers correctly.
                # If we reach here, it's a standalone minus, which is not supported as an operator.
                 raise SQLSyntaxError(f"Unexpected minus sign at pos {pos}", pos)
            elif char == "=" or char == "!" or char == "<" or char == ">" or char == "":
                # Handle compound operators like !=, <=, >=, <> (which maps to !=)
                op_lexeme = char
                next_char = sql[i+1] if i+1 < n else None

                if op_lexeme == "!" and next_char == "=":
                    op_lexeme += "="
                elif op_lexeme == "<" and next_char in ("=", ">"): # Should not happen based on spec, but for robustness
                     op_lexeme += next_char
                elif op_lexeme == ">" and next_char == "=":
                     op_lexeme += "="
                elif op_lexeme == "<" and next_char == "=":
                     op_lexeme += "="
                elif op_lexeme == "=" and next_char == "=" and i+2 < n and sql[i+2] == "<":
                     # This path is overly complex for the spec, let's handle known operators directly
                     pass

                if op_lexeme in OPERATOR_SET:
                    # Special handling for <> -> !=
                    if op_lexeme == "<>" or op_lexeme == "!=":
                        tokens.append(Token("OP", "!=", pos))
                    else:
                        tokens.append(Token("OP", op_lexeme, pos))
                    i += len(op_lexeme)
                    continue

            elif char in ",()*":
                tokens.append(Token(char.upper(), char, pos))
                i += 1
                continue

        # Handle single character operators not caught above
        elif char in "=!<>":
            op_lexeme = char
            next_char = sql[i+1] if i+1 < n else None

            if op_lexeme == "!" and next_char == "=":
                op_lexeme += "="
            elif op_lexeme == "<" and next_char == "=":
                op_lexeme += "="
            elif op_lexeme == ">" and next_char == "=":
                op_lexeme += "="

            if op_lexeme in OPERATOR_SET:
                tokens.append(Token("OP", op_lexeme, i))
                i += len(op_lexeme)
                continue

        # Unknown character
        else:
            raise SQLSyntaxError(f"Unknown character '{char}' at pos {i}", i)

        i += 1

    # Append EOF token
    tokens.append(Token("EOF", None, n))
    return tokens
