from dataclasses import dataclass
from typing import List, Optional, Tuple, Any, Union

# Assume Token and SQLSyntaxError are imported from minisql.tokens
from .tokens import Token, SQLSyntaxError

# --- AST Definitions ---

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Any  # int, float, str, bool, or None (for NULL)

@dataclass(frozen=True)
class Compare:
    op: str  # =, !=, <, <=, >, >=
    left: Union[Column, Literal]
    right: Union[Column, Literal]

@dataclass(frozen=True)
class And:
    left: Union[Compare, And, Or, Not, IsNull]
    right: Union[Compare, And, Or, Not, IsNull]

@dataclass(frozen=True)
class Or:
    left: Union[Compare, And, Or, Not, IsNull]
    right: Union[Compare, And, Or, Not, IsNull]

@dataclass(frozen=True)
class Not:
    operand: Union[Compare, And, Or, Not, IsNull]

@dataclass(frozen=True)
class IsNull:
    operand: Union[Column, Literal]
    negated: bool  # True for IS NOT NULL

@dataclass(frozen=True)
class Select:
    columns: Optional[List[str]]  # None for *, list of names for specific columns
    table: str
    where: Optional[Union[Compare, And, Or, Not, IsNull]]
    order_by: List[Tuple[str, bool]]  # (name, descending)
    limit: Optional[int]

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        # Ensure we don't index out of bounds, although EOF token should handle this
        if self.pos >= len(self.tokens):
            return Token('EOF', None, len(self.tokens[-1].value if self.tokens else 0))
        return self.tokens[self.pos]

    def consume(self, expected_kind: Optional[str] = None, expected_value: Optional[str] = None) -> Token:
        token = self.tokens[self.pos]
        if expected_kind and token.kind != expected_kind:
            raise SQLSyntaxError(f"Expected token kind {expected_kind} but got {token.kind} ({token.value})", token.pos)
        if expected_value and token.value != expected_value:
            raise SQLSyntaxError(f"Expected token value '{expected_value}' but got '{token.value}'", token.pos)
        self.pos += 1
        return token

    def skip_whitespace(self):
        while self.peek().kind == 'SKIP' or (self.peek().value is None and self.peek().kind != 'EOF'):
            self.pos += 1

    # Grammar Rule: Statement ::= SELECT select_list FROM table [WHERE condition] [ORDER BY order_item {, order_item}] [LIMIT n]
    def parse(self) -> Select:
        self.skip_whitespace()

        # 1. SELECT select_list
        select_token = self.consume('KEYWORD', 'SELECT')
        self.skip_whitespace()
        select_list_tokens = []
        while True:
            token = self.peek()
            if token.kind == 'IDENT' or token.kind == 'STAR':
                select_list_tokens.append(self.consume().value)
            elif token.kind == 'COMMA':
                self.consume('COMMA')
                select_list_tokens.append(self.consume().value)
            else:
                break

        columns = None
        if len(select_list_tokens) == 1 and select_list_tokens[0] == '*':
            columns = None
        elif len(select_list_tokens) > 0:
            # Check for duplicates in select list
            names = [t for t in select_list_tokens if t not in (',', '*')]
            if len(names) != len(set(names)): 
                raise SQLSyntaxError("Duplicate name in select list", select_list_tokens[0].pos)
            columns = names

        # 2. FROM table
        self.skip_whitespace()
        from_token = self.consume('KEYWORD', 'FROM')
        self.skip_whitespace()
        table_token = self.consume('IDENT')
        table_name = table_token.value

        where_condition = None
        order_by_items = []
        limit_n = None

        # 3. [WHERE condition]
        self.skip_whitespace()
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'WHERE':
            self.consume('KEYWORD', 'WHERE')
            self.skip_whitespace()
            where_condition = self._parse_condition()

        # 4. [ORDER BY order_item {, order_item}]
        self.skip_whitespace()
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'ORDER':
            self.consume('KEYWORD', 'ORDER')
            self.consume('KEYWORD', 'BY')
            self.skip_whitespace()
            order_by_items = self._parse_order_by()

        # 5. [LIMIT n]
        self.skip_whitespace()
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'LIMIT':
            self.consume('KEYWORD', 'LIMIT')
            self.skip_whitespace()
            limit_token = self.consume('NUMBER')
            try:
                # Ensure limit is a non-negative integer
                limit_n = int(float(limit_token.value))
                if limit_n < 0: raise ValueError
            except ValueError:
                raise SQLSyntaxError("LIMIT value must be a non-negative integer", limit_token.pos)

        # Check for EOF or other tokens after the statement ends
        self.skip_whitespace()
        if self.peek().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token {self.peek().value} after statement end", self.peek().pos)

        return Select(
            columns=columns,
            table=table_name,
            where=where_condition,
            order_by=order_by_items,
            limit=limit_n
        )

    # --- Grammar Sub-Parsers ---

    def _parse_condition(self) -> Union[Compare, And, Or, Not, IsNull]:
        # Lowest precedence: OR (Left-associative)
        left = self._parse_and()
        while self.peek().kind == 'KEYWORD' and self.peek().value == 'OR':
            self.consume('KEYWORD', 'OR')
            right = self._parse_and()
            left = Or(left=left, right=right)
        return left

    def _parse_and(self) -> Union[Compare, And, Or, Not, IsNull]:
        # Next precedence: AND (Left-associative)
        left = self._parse_not()
        while self.peek().kind == 'KEYWORD' and self.peek().value == 'AND':
            self.consume('KEYWORD', 'AND')
            right = self._parse_not()
            left = And(left=left, right=right)
        return left

    def _parse_not(self) -> Union[Compare, And, Or, Not, IsNull]:
        # Next precedence: NOT
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT':
            self.consume('KEYWORD', 'NOT')
            operand = self._parse_primary_condition() # NOT applies to a primary condition
            return Not(operand=operand)
        return self._parse_primary_condition()

    def _parse_primary_condition(self) -> Union[Compare, IsNull]:
        # Primary condition: (condition) | operand op operand | operand IS [NOT] NULL

        # Check for IS NULL
        if self.peek().kind == 'IDENT' and self.peek().value == 'IS':
            self.consume('IDENT', 'IS')
            self.skip_whitespace()
            null_check_token = self.peek()

            if null_check_token.kind == 'KEYWORD' and null_check_token.value == 'NULL':
                self.consume('KEYWORD', 'NULL')
                # Check for IS NOT NULL
                negated = False
                self.skip_whitespace()
                if self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT':
                    self.consume('KEYWORD', 'NOT')
                    negated = True 

                # negated=True means IS NOT NULL
                return IsNull(operand=self._parse_operand(), negated=negated)
            else:
                 raise SQLSyntaxError("Expected NULL after IS", null_check_token.pos)

        # Otherwise, it must be a binary comparison (operand op operand)
        return self._parse_comparison()

    def _parse_comparison(self) -> Compare:
        left = self._parse_operand()
        self.skip_whitespace()
        op_token = self.peek()

        if op_token.kind == 'OP':
            self.consume('OP')
            right = self._parse_operand()
            return Compare(op=op_token.value, left=left, right=right)
        else:
            # If we hit here, it means we expected a comparison operator but found something else.
            raise SQLSyntaxError("Expected comparison operator (=, !=, <, etc.)", op_token.pos)

    def _parse_operand(self) -> Union[Column, Literal]:
        token = self.peek()
        self.skip_whitespace()

        if token.kind == 'IDENT':
            # Name (Column identifier)
            self.consume('IDENT')
            return Column(name=token.value)
        elif token.kind == 'NUMBER':
            # Number literal
            self.consume('NUMBER')
            try:
                if '.' in token.value:
                    return Literal(value=float(token.value))
                else:
                    return Literal(value=int(token.value))
            except ValueError:
                 raise SQLSyntaxError("Invalid number format", token.pos)
        elif token.kind == 'STRING':
            # String literal
            self.consume('STRING')
            return Literal(value=token.value)
        elif token.kind == 'KEYWORD' and token.value == 'NULL':
            # NULL literal
            self.consume('KEYWORD', 'NULL')
            return Literal(value=None)
        elif token.kind == 'KEYWORD' and token.value == 'TRUE':
            # Boolean literal
            self.consume('KEYWORD', 'TRUE')
            return Literal(value=True)
        elif token.kind == 'KEYWORD' and token.value == 'FALSE':
            # Boolean literal
            self.consume('KEYWORD', 'FALSE')
            return Literal(value=False)
        else:
            raise SQLSyntaxError(f"Expected operand (IDENT, NUMBER, STRING, NULL, TRUE, FALSE) but got {token.kind} ({token.value})", token.pos)

    def _parse_order_by(self) -> List[Tuple[str, bool]]:
        order_items = []
        while True:
            # Parse name (IDENT)
            name_token = self.consume('IDENT')
            name = name_token.value
            descending = False
            self.skip_whitespace()

            # Check for ASC/DESC
            if self.peek().kind == 'KEYWORD':
                keyword = self.peek().value
                if keyword == 'DESC':
                    self.consume('KEYWORD', 'DESC')
                    descending = True
                elif keyword == 'ASC':
                    self.consume('KEYWORD', 'ASC')
                    descending = False

            order_items.append((name, descending))
            self.skip_whitespace()

            # Check for comma or end of ORDER BY clause
            if self.peek().kind == 'COMMA':
                self.consume('COMMA')
            else:
                break
        return order_items

# Entry point function
def parse(sql: str) -> Select:
    from .tokens import tokenize # Import inside function to avoid circular dependency issues during initial load

    # 1. Tokenize
    tokens = tokenize(sql)

    # 2. Parse
    parser = Parser(tokens)
    return parser.parse()

