            except ValueError as e:
                raise ValueError(f"Unknown type provided: {e}")

        if parent_code is not None:
            if parent_code not in self._accounts:
                raise ValueError(f"Parent code {parent_code} does not exist.")
            parent_account = self._accounts[parent_code]
            # Rule: Parent must be of the same type. This is a simplification, typically only related accounts link.
            # Sticking strictly to the requirement: 'parent of a different type'.
            if parent_account.type != account_type:
                raise ValueError("Parent and child accounts must be of the same type.")

        new_account = Account(code=code, name=name, type=account_type, parent=parent_code)
        self._accounts[code] = new_account
        return new_account

    def get(self, code: str) -> Account:
        """Retrieves an account by its code."""
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found.")
        return self._accounts[code]

    def children(self, code: str) -> List[Account]:
        """Returns all direct children of an account, sorted by code."""
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found.")

        children_list = []
        for account in self._accounts.values():
            if account.parent == code:
                children_list.append(account)

        return sorted(children_list, key=lambda c: c.code)

    def roots(self) -> List[Account]:
        """Returns all root accounts (no parent), sorted by code."""
        return sorted([acc for acc in self._accounts.values() if acc.parent is None], key=lambda c: c.code)

    def is_leaf(self, code: str) -> bool:
        """Checks if an account has no children."""
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found.")
        return not self.children(code)

    def walk(self) -> List[Tuple[Account, int]]:
        """Performs a depth-first traversal of the chart, yielding account and depth.
        Roots and siblings are ordered by code."""
        result: List[Tuple[Account, int]] = []
        roots = self.roots()
        stack: List[Tuple[Account, int]] = []

        # Push roots onto the stack in reverse code order so they are popped in code order
        for root in reversed(roots):
            stack.append((root, 0))

        while stack:
            current_account, depth = stack.pop()
            result.append((current_account, depth))

            # Get children sorted by code
            children = self.children(current_account.code)

            # Push children onto the stack in reverse code order so they are popped in code order
            for child in reversed(children):
                stack.append((child, depth + 1))

        return result

