        all_descendants_with_depth = self.chart.walk()
        descendant_codes = {acc.code for acc, depth in all_descendants_with_depth if acc.code == code or self._is_descendant(code, acc.code)}

        balance_debit = Decimal('0')
        balance_credit = Decimal('0')

        for entry in self.entries():
