from enum import Enum
from dataclasses import dataclass
from typing import Optional, List, Tuple
from decimal import Decimal, InvalidOperation

class AccountType(Enum):
    ASSET = "asset"
    LIABILITY = "liability"
    EQUITY = "equity"
    INCOME = "income"
    EXPENSE = "expense"

@dataclass(frozen=True)
class Account:
    code: str
    name: str
    type: AccountType
    parent: Optional[str]

class Chart:
    def __init__(self):
        self._accounts: dict[str, Account] = {}

    def _validate_code(self, code: str):
        if not code.isdigit() or not code:
            raise ValueError("Account code must be a non-empty string of digits.")

    def _validate_type(self, type_input):
        if isinstance(type_input, str):
            type_input = type_input.lower()
            if type_input not in {e.value for e in AccountType}:
                raise ValueError(f"Unknown account type: {type_input}")
            return AccountType(type_input)
        elif isinstance(type_input, AccountType):
            return type_input
        else:
            raise TypeError("Account type must be an AccountType enum or its string value.")

    def add(self, code: str, name: str, type_input, parent: Optional[str] = None) -> Account:
        self._validate_code(code)
        account_type = self._validate_type(type_input)

        if code in self._accounts:
            raise ValueError(f"Account code '{code}' already exists.")

        if parent is not None:
            if parent not in self._accounts:
                raise ValueError(f"Parent account code '{parent}' does not exist.")
            parent_account = self._accounts[parent]
            if parent_account.type != account_type:
                raise ValueError("Parent and child accounts must be of the same type.")

        new_account = Account(code=code, name=name, type=account_type, parent=parent)
        self._accounts[code] = new_account
        return new_account

    def get(self, code: str) -> Account:
        if code not in self._accounts:
            raise KeyError(f"Account code '{code}' not found in chart.")
        return self._accounts[code]

    def children(self, code: str) -> List[Account]:
        if code not in self._accounts:
            raise KeyError(f"Account code '{code}' not found in chart.")
        children_list = [acc for code, acc in self._accounts.items() if acc.parent == code]
        return sorted(children_list, key=lambda a: a.code)

    def roots(self) -> List[Account]:
        return sorted([acc for acc in self._accounts.values() if acc.parent is None], key=lambda a: a.code)

    def is_leaf(self, code: str) -> bool:
        if code not in self._accounts:
            raise KeyError(f"Account code '{code}' not found in chart.")
        return not self.children(code)

    def walk(self) -> List[Tuple[Account, int]]:
        # DFS walk, depth-first, ordered by code
        accounts = self.roots()
        walk_order: List[Tuple[Account, int]] = []

        def dfs(accounts_to_process: List[Account], depth: int):
            for account in accounts_to_process:
                # Add current account
                walk_order.append((account, depth))

                # Get children, already sorted by code
                children = self.children(account.code)
                if children: 
                    # Recurse on children
                    dfs(children, depth + 1)

        dfs(accounts, 0)
        return walk_order

