from datetime import date as date_type
from dataclasses import dataclass
from typing import List, Tuple
from decimal import Decimal, InvalidOperation
from collections import namedtuple

# Assuming AccountType, Account, Chart are imported from .accounts
from .accounts import Chart, AccountType

class UnbalancedEntryError(ValueError):
    pass

@dataclass(frozen=True)
class Line:
    account: str
    debit: Decimal = Decimal('0')
    credit: Decimal = Decimal('0')

@dataclass(frozen=True)
class Entry:
    number: int
    day: date_type
    memo: str
    lines: Tuple[Line, ...]

# LedgerRow: (number, day, memo, debit, credit, balance)
LedgerRow = namedtuple('LedgerRow', ['number', 'day', 'memo', 'debit', 'credit', 'balance'])

class Journal:
    def __init__(self, chart: Chart):
        self.chart = chart
        self.entries: List[Entry] = []
        self._next_entry_number = 1

    def _convert_to_decimal(self, amount) -> Decimal:
        if isinstance(amount, float):
            raise TypeError("Floats are not allowed for monetary amounts.")
        try:
            dec = Decimal(str(amount))
        except InvalidOperation:
            raise ValueError(f"Invalid monetary value: {amount}")

        if dec < Decimal('0'):
            raise ValueError("Amount cannot be negative.")

        # Check for more than two decimal places
        if dec.as_tuple().exponent < -2:
            raise ValueError("Amount must have at most two decimal places.")
        return dec

    def post(self, day: date_type, memo: str, lines_data: List[Tuple[str, Decimal, Decimal]]) -> Entry:
        # 1. Check for at least two lines
        if len(lines_data) < 2:
            raise ValueError("An entry must have at least two lines.")

        temp_lines: List[Line] = []
        total_debits = Decimal('0')
        total_credits = Decimal('0')

        # Process lines to validate amounts and existence
        for account_code, debit_raw, credit_raw in lines_data:
            # 3. Validate amounts and one side non-zero
            try:
                debit = self._convert_to_decimal(debit_raw)
                credit = self._convert_to_decimal(credit_raw)
            except (TypeError, ValueError) as e:
                # Re-raise to match specific requirements if needed, but keeping general validation here
                raise ValueError(f"Invalid amount in line for account {account_code}: {e}")

            if debit > Decimal('0') and credit > Decimal('0'):
                raise ValueError("Each line can have at most one non-zero amount (either debit or credit).")

            # 2. Check account existence and if it's a leaf
            try:
                account = self.chart.get(account_code)
                if not self.chart.is_leaf(account_code):
                    raise ValueError(f"Account {account_code} is not a leaf account.")
            except KeyError as e:
                raise KeyError(f"Account {account_code} does not exist.") from e

            temp_lines.append(Line(account=account_code, debit=debit, credit=credit))
            total_debits += debit
            total_credits += credit

        # 4. Check balance
        if total_debits != total_credits:
            raise UnbalancedEntryError(f"Entry is unbalanced: Debits ({total_debits}) != Credits ({total_credits}).")

        # Record entry
        new_entry = Entry(
            number=self._next_entry_number,
            day=day,
            memo=memo,
            lines=tuple(temp_lines)
        )
        self.entries.append(new_entry)
        self._next_entry_number += 1
        return new_entry

    def entries(self) -> List[Entry]:
        return sorted(self.entries, key=lambda e: e.number)

    def balance(self, code: str, start: Optional[date_type] = None, end: Optional[date_type] = None) -> Decimal:
        try:
            account = self.chart.get(code)
        except KeyError as e:
            raise e

        # Determine if the account is debit-normal
        is_debit_normal = account.type in [AccountType.ASSET, AccountType.EXPENSE]

        # Identify all descendant codes including self
        descendant_codes = {code}
        queue = [account]
        while queue:
            current = queue.pop(0)
            for child in self.chart.children(current.code):
                descendant_codes.add(child.code)
                queue.append(child)

        balance = Decimal('0')

        # Filter entries based on date range
        filtered_entries = [e for e in self.entries() if (start is None or e.day >= start) and (end is None or e.day <= end)]

        # Aggregate all relevant lines from filtered entries
        all_relevant_lines = []
        for entry in filtered_entries:
            for line in entry.lines:
                if line.account in descendant_codes:
                    all_relevant_lines.append(line)

        # Calculate running balance (this is tricky without simulating ledger row by row, but we need the final balance)
        # Since the requirement is 'the account's balance on its normal side', we sum up contributions.
        total_debit_contribution = Decimal('0')
        total_credit_contribution = Decimal('0')

        for line in all_relevant_lines:
            if line.debit > Decimal('0'):
                total_debit_contribution += line.debit
            if line.credit > Decimal('0'):
                total_credit_contribution += line.credit

        if is_debit_normal:
            return total_debit_contribution - total_credit_contribution
        else: # Credit normal
            return total_credit_contribution - total_debit_contribution

    def ledger(self, code: str) -> List[LedgerRow]:
        try:
            account = self.chart.get(code)
        except KeyError as e:
            raise e

        is_debit_normal = account.type in [AccountType.ASSET, AccountType.EXPENSE]

        # Identify all descendant codes including self
        descendant_codes = {code}
        queue = [account]
        while queue:
            current = queue.pop(0)
            for child in self.chart.children(current.code):
                descendant_codes.add(child.code)
                queue.append(child)

        ledger_rows: List[LedgerRow] = []
        running_balance = Decimal('0')

        # Sort entries by day, then number
        sorted_entries = sorted(self.entries(), key=lambda e: (e.day, e.number))

        for entry in sorted_entries:
            entry_lines = sorted(entry.lines, key=lambda l: (l.account, l.debit, l.credit)) # Sort by line position (implied by tuple order)
            entry_memo = entry.memo
            entry_number = entry.number
            entry_day = entry.day

            for line in entry_lines:
                if line.account not in descendant_codes:
                    continue

                debit_amount = line.debit
                credit_amount = line.credit

                # Update running balance based on normal side
                if is_debit_normal:
                    if debit_amount > Decimal('0'):
                        running_balance += debit_amount
                    if credit_amount > Decimal('0'):
                        running_balance -= credit_amount
                else: # Credit normal
                    if credit_amount > Decimal('0'):
                        running_balance += credit_amount
                    if debit_amount > Decimal('0'):
                        running_balance -= debit_amount

                row = LedgerRow(
                    number=entry_number,
                    day=entry_day,
                    memo=entry_memo,
                    debit=debit_amount,
                    credit=credit_amount,
                    balance=running_balance
                )
                ledger_rows.append(row)

        return ledger_rows

