from .journal import Journal, Entry, Line
from .accounts import Chart, Account, AccountType
from datetime import date as date_type
from decimal import Decimal
from typing import Dict

# Helper function for formatting amounts
def _format_amount(amount: Decimal) -> str:
    # Ensures exactly two decimals and leading minus if negative
    return f"{amount:.2f}"

# Helper to calculate balance for a set of entries
def _calculate_period_balance(journal: Journal, code: str, start: Optional[date_type], end: Optional[date_type], is_debit_normal: bool) -> Decimal:
    # Reuses logic from Journal.balance but ensures only the final balance is returned for reporting context
    # For statements, we need the *net* balance contribution over the period.

    # In this simplified context, we iterate over relevant lines to sum contributions.
    # We must replicate the descendant logic here or rely on Journal's internal structure if exposed.

    try:
        account = journal.chart.get(code)
        descendant_codes = {code}
        queue = [account]
        while queue:
            current = queue.pop(0)
            for child in journal.chart.children(current.code):
                descendant_codes.add(child.code)
                queue.append(child)
    except KeyError: # Should not happen if called correctly
        return Decimal('0')

    total_debit_contribution = Decimal('0')
    total_credit_contribution = Decimal('0')

    filtered_entries = [e for e in journal.entries() if (start is None or e.day >= start) and (end is None or e.day <= end)]

    for entry in filtered_entries:
        for line in entry.lines:
            if line.account in descendant_codes:
                if line.debit > Decimal('0'):
                    total_debit_contribution += line.debit
                if line.credit > Decimal('0'):
                    total_credit_contribution += line.credit

    if is_debit_normal:
        return total_debit_contribution - total_credit_contribution
    else: # Credit normal
        return total_credit_contribution - total_debit_contribution


def trial_balance(journal: Journal, as_of: Optional[date_type] = None) -> str:
    lines = []
    if as_of:
        lines.append(f"TRIAL BALANCE as of {as_of.strftime('%Y-%m-%d')}")
    else:
        lines.append("TRIAL BALANCE")

    chart = journal.chart
    total_debits = Decimal('0')
    total_credits = Decimal('0')
    account_balances: Dict[str, Decimal] = {}

    # Get all accounts in walk order
    walk_list = chart.walk()

    for account, _ in walk_list:
        account_obj = chart.get(account.code)
        is_debit_normal = account_obj.type in [AccountType.ASSET, AccountType.EXPENSE]

        # Calculate balance over the required period
        balance = _calculate_period_balance(journal, account.code, start=None, end=as_of) # Note: Trial Balance usually runs until AS OF date if specified

        if balance == Decimal('0'):
            continue

        # Determine contribution to totals
        if is_debit_normal:
            # Debit normal: Positive balance is Debit, Negative balance is Credit
            if balance > Decimal('0'):
                total_debits += balance
                lines.append(f"{account.code} {account.name}: {_format_amount(balance)}")
            else:
                # Negative balance -> credit side
                total_credits += abs(balance)
                lines.append(f"{account.code} {account.name}: {_format_amount(balance)}") # Prints with leading minus
        else: # Credit normal
            # Credit normal: Positive balance is Credit, Negative balance is Debit
            if balance > Decimal('0'):
                total_credits += balance
                lines.append(f"{account.code} {account.name}: {_format_amount(balance)}")
            else:
                # Negative balance -> debit side
                total_debits += abs(balance)
                lines.append(f"{account.code} {account.name}: {_format_amount(balance)}")

    # Totals lines
    lines.append(f"Total debits: {_format_amount(total_debits)}")
    lines.append(f"Total credits: {_format_amount(total_credits)}")

    return "\n".join(lines) + "\n"

def income_statement(journal: Journal, start: date_type, end: date_type) -> str:
    if start > end:
        raise ValueError("Start date cannot be after end date for Income Statement.")

    lines = []
    lines.append(f"INCOME STATEMENT {start.strftime('%Y-%m-%d')} to {end.strftime('%Y-%m-%d')}")

    chart = journal.chart
    income_accounts = [acc for acc in chart.roots() if acc.type == AccountType.INCOME]
    expense_accounts = [acc for acc in chart.roots() if acc.type == AccountType.EXPENSE]

    total_income = Decimal('0')
    total_expenses = Decimal('0')
    income_lines: List[str] = []
    expense_lines: List[str] = []

    # --- Income Section ---
    lines.append("Income")
    for account, _ in chart.walk():
        account_obj = chart.get(account.code)
        if account_obj.type == AccountType.INCOME:
            is_debit_normal = account_obj.type in [AccountType.ASSET, AccountType.EXPENSE] # False for INCOME

            balance = _calculate_period_balance(journal, account.code, start, end, is_debit_normal)

            if balance != Decimal('0'):
                # Income is credit normal, so positive balance is income
                contribution = balance if balance > Decimal('0') else Decimal('0')
                total_income += contribution

                # Format account line based on depth
                depth = account_obj.parent is None and account_obj.code == account.code and len(chart.roots())==1 and account.code == chart.roots()[0].code and account_obj.type == AccountType.INCOME # Rough depth approximation for root
                if account_obj.parent: 
                    try:
                         parent_account = chart.get(account_obj.parent)
                         # Calculate depth by traversing up from the account
                         depth = 0
                         temp = account_obj
                         while temp.parent: 
                             depth += 1
                             try:
                                 temp = chart.get(temp.parent)
                             except KeyError:
                                 break
                    except KeyError:
                         depth = 0 # Should not happen
                else: 
                    depth = 0 # Root level

                indent = '  ' * depth
                formatted_line = f"{indent}{account.code} {account.name}: {_format_amount(balance)}"
                income_lines.append(formatted_line)

    lines.extend(income_lines)
    lines.append(f"Total income: {_format_amount(total_income)}")

    # --- Expenses Section ---
    lines.append("Expenses")
    for account, _ in chart.walk():
        account_obj = chart.get(account.code)
        if account_obj.type == AccountType.EXPENSE:
            is_debit_normal = account_obj.type in [AccountType.ASSET, AccountType.EXPENSE] # True for EXPENSE

            balance = _calculate_period_balance(journal, account.code, start, end, is_debit_normal)

            if balance != Decimal('0'):
                # Expense is debit normal, so positive balance is expense
                contribution = balance if balance > Decimal('0') else Decimal('0')
                total_expenses += contribution

                # Format account line based on depth
                if account_obj.parent: 
                    try:
                         depth = 0
                         temp = account_obj
                         while temp.parent: 
                             depth += 1
                             try:
                                 temp = chart.get(temp.parent)
                             except KeyError:
                                 break
                    except KeyError:
                         depth = 0
                else: 
                    depth = 0

                indent = '  ' * depth
                formatted_line = f"{indent}{account.code} {account.name}: {_format_amount(balance)}"
                expense_lines.append(formatted_line)

    lines.extend(expense_lines)
    lines.append(f"Total expenses: {_format_amount(total_expenses)}")

    # --- Net Income ---
    net_income = total_income - total_expenses
    lines.append(f"Net income: {_format_amount(net_income)}")

    return "\n".join(lines) + "\n"

