from enum import Enum
from dataclasses import dataclass
from typing import List, Optional, Tuple, Dict, NamedTuple
from decimal import Decimal, InvalidOperation
import datetime

# --- Account Definitions (from accounts.py) ---

class AccountType(Enum):
    ASSET = "asset"
    LIABILITY = "liability"
    EQUITY = "equity"
    INCOME = "income"
    EXPENSE = "expense"

    @classmethod
    def from_string(cls, value: str) -> "AccountType":
        try:
            return cls(value.lower())
        except ValueError:
            raise ValueError(f"Unknown account type: {value}")

@dataclass(frozen=True)
class Account:
    code: str
    name: str
    type: AccountType
    parent: Optional[str] = None

class Chart:
    """Manages the hierarchical structure of the chart of accounts."""
    def __init__(self):
        self._accounts: Dict[str, Account] = {}

    def add(self, code: str, name: str, account_type: AccountType | str, parent_code: Optional[str] = None) -> Account:
        """Adds a new account to the chart with validation."""
        if not code.isdigit() or not code: 
            raise ValueError("Account code must be a non-empty string of digits.")

        if code in self._accounts:
            raise ValueError(f"Account code {code} already exists.")

        if isinstance(account_type, str):
            try:
                account_type = AccountType.from_string(account_type)
            except ValueError as e:
                raise ValueError(f"Unknown type provided: {e}")

        if parent_code is not None:
            if parent_code not in self._accounts:
                raise ValueError(f"Parent code {parent_code} does not exist.")
            parent_account = self._accounts[parent_code]
            # Rule: Parent must be of the same type. This is a simplification, typically only related accounts link.
            # Sticking strictly to the requirement: 'parent of a different type'.
            if parent_account.type != account_type:
                raise ValueError("Parent and child accounts must be of the same type.")

        new_account = Account(code=code, name=name, type=account_type, parent=parent_code)
        self._accounts[code] = new_account
        return new_account

    def get(self, code: str) -> Account:
        """Retrieves an account by its code."""
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found.")
        return self._accounts[code]

    def children(self, code: str) -> List[Account]:
        """Returns all direct children of an account, sorted by code."""
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found.")

        children_list = []
        for account in self._accounts.values():
            if account.parent == code:
                children_list.append(account)

        return sorted(children_list, key=lambda c: c.code)

    def roots(self) -> List[Account]:
        """Returns all root accounts (no parent), sorted by code."""
        return sorted([acc for acc in self._accounts.values() if acc.parent is None], key=lambda c: c.code)

    def is_leaf(self, code: str) -> bool:
        """Checks if an account has no children."""
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found.")
        return not self.children(code)

    def walk(self) -> List[Tuple[Account, int]]:
        """Performs a depth-first traversal of the chart, yielding account and depth.
        Roots and siblings are ordered by code."""
        result: List[Tuple[Account, int]] = []
        roots = self.roots()
        stack: List[Tuple[Account, int]] = []

        # Push roots onto the stack in reverse code order so they are popped in code order
        for root in reversed(roots):
            stack.append((root, 0))

        while stack:
            current_account, depth = stack.pop()
            result.append((current_account, depth))

            # Get children sorted by code
            children = self.children(current_account.code)

            # Push children onto the stack in reverse code order so they are popped in code order
            for child in reversed(children):
                stack.append((child, depth + 1))

        return result

# --- Journal Definitions (books/journal.py) ---

class UnbalancedEntryError(ValueError):
    """Raised when debits and credits of an entry do not balance."""
    pass

class Line:  # Frozen dataclass equivalent via NamedTuple for simplicity/immutability if not using Python 3.12 dataclasses fully for everything
    __slots__ = ('account', 'debit', 'credit')
    def __init__(self, account: str, debit: Decimal = Decimal('0'), credit: Decimal = Decimal('0')):
        self.account = account
        self.debit = debit
        self.credit = credit

    def __repr__(self):
        return f"Line(account='{self.account}', debit={self.debit}, credit={self.credit})"

class Entry: # Frozen dataclass
    __slots__ = ('number', 'day', 'memo', 'lines')
    def __init__(self, number: int, day: datetime.date, memo: str, lines: Tuple[Line, ...]):
        self.number = number
        self.day = day
        self.memo = memo
        self.lines = lines

    def __repr__(self):
        return f"Entry(number={self.number}, day={self.day}, memo='{self.memo}', lines={len(self.lines)})"

class LedgerRow(NamedTuple):
    number: int
    day: datetime.date
    memo: str
    debit: Decimal
    credit: Decimal
    balance: Decimal

class Journal:
    """Main ledger keeping all journal entries."""
    def __init__(self, chart: Chart):
        self.chart = chart
        self.entries: List[Entry] = []
        self._next_entry_number = 1

    def _validate_amount(self, amount) -> Decimal:
        """Converts input to Decimal, validating types and range."""
        if isinstance(amount, float):
            raise TypeError("Amounts must be Decimal, int, or str, not float.")
        try:
            decimal_amount = Decimal(str(amount))
        except InvalidOperation:
            raise ValueError("Invalid amount format provided.")

        if decimal_amount < Decimal('0'):
            raise ValueError("Amount cannot be negative.")
        if decimal_amount.as_tuple().exponent < -2:
            raise ValueError("Amount must have at most two decimal places.")
        return decimal_amount

    def post(self, day: datetime.date, memo: str, lines: List[Line]) -> Entry:
        """Posts a new journal entry after strict validation."""

        # 1. there are at least two lines (ValueError)
        if len(lines) < 2:
            raise ValueError("Journal entry must contain at least two lines.")

        total_debit = Decimal('0')
        total_credit = Decimal('0')

        processed_lines = []
        for line in lines:
            # 2. each line's account exists (KeyError) and is a leaf (ValueError)
            try:
                account = self.chart.get(line.account)
            except KeyError:
                raise KeyError(f"Account code {line.account} does not exist in the chart.")

            if not self.chart.is_leaf(line.account):
                raise ValueError(f"Account {line.account} is not a leaf account.")

            # 3. each line's amounts are valid, and exactly one of debit/credit is non-zero (ValueError)
            try:
                debit = self._validate_amount(line.debit)
                credit = self._validate_amount(line.credit)
            except (TypeError, ValueError) as e:
                raise e

            if debit > Decimal('0') and credit > Decimal('0') or debit == Decimal('0') and credit == Decimal('0') or debit < Decimal('0') or credit < Decimal('0'):
                 raise ValueError("Each line must have exactly one non-zero amount (debit or credit).")

            processed_lines.append(Line(line.account, debit, credit))
            total_debit += processed_lines[-1].debit
            total_credit += processed_lines[-1].credit

        # 4. the debits and credits total the same (UnbalancedEntryError)
        if total_debit != total_credit:
            raise UnbalancedEntryError(f"Entry is unbalanced: Debits={total_debit}, Credits={total_credit}.")

        # Record entry
        entry = Entry(
            number=self._next_entry_number,
            day=day,
            memo=memo,
            lines=tuple(processed_lines)
        )
        self.entries.append(entry)
        self._next_entry_number += 1
        return entry

    def entries(self) -> List[Entry]:
        """Returns all posted entries in number order."""
        # Since we append sequentially, they are already in number order
        return self.entries

    def balance(self, code: str, start: Optional[datetime.date] = None, end: Optional[datetime.date] = None) -> Decimal:
        """Calculates the account's balance on its normal side.
        (debits - credits for debit-normal; credits - debits otherwise).
        Counts self and all descendants, within date range.
        """
        try:
            account = self.chart.get(code)
        except KeyError:
            raise KeyError(f"Account code {code} not found.")

        # Determine normal side: Debit-normal if ASSET or EXPENSE
        is_debit_normal = account.type in [AccountType.ASSET, AccountType.EXPENSE]

        # Get all accounts that are descendants or self, ordered by depth-first walk
        all_descendants_with_depth = self.chart.walk()
        descendant_codes = {acc.code for acc, depth in all_descendants_with_depth if acc.code == code or self._is_descendant(code, acc.code)}

        balance_debit = Decimal('0')
        balance_credit = Decimal('0')

        for entry in self.entries():
            for line in entry.lines:
                line_account_code = line.account

                # Check if this line relates to the target account or its descendants
                if line_account_code in descendant_codes and self._is_date_in_range(entry.day, start, end):
                    if line.debit > Decimal('0'):
                        balance_debit += line.debit
                    elif line.credit > Decimal('0'):
                        balance_credit += line.credit

        # Calculate net balance on the normal side
        if is_debit_normal:
            return balance_debit - balance_credit
        else: # Credit normal
            return balance_credit - balance_debit

    def ledger(self, code: str) -> List[LedgerRow]:
        """Returns one row per line posted to the account or a descendant, in chronological order."""
        try:
            account = self.chart.get(code)
        except KeyError:
            raise KeyError(f"Account code {code} not found.")

        descendant_codes = {acc.code for acc, depth in self.chart.walk() if acc.code == code or self._is_descendant(code, acc.code)}

        # Collect all relevant ledger rows (lines posted to self or descendants)
        all_rows_data: List[Tuple[datetime.date, int, Line]] = []
        for entry in self.entries():
            for line in entry.lines:
                if line.account in descendant_codes:
                    all_rows_data.append((entry.day, entry.number, line))

        # Sort: day, then entry number, then line position (implicit by tuple order)
        all_rows_data.sort(key=lambda x: (x[0], x[1]))

        ledger_rows: List[LedgerRow] = []
        running_balance = Decimal('0')
        is_debit_normal = account.type in [AccountType.ASSET, AccountType.EXPENSE]

        for day, entry_num, line in all_rows_data:
            debit = line.debit
            credit = line.credit

            # Update running balance based on normal side
            if is_debit_normal:
                # Debit increases balance, Credit decreases balance
                running_balance = running_balance + debit - credit
            else: # Credit normal
                # Credit increases balance, Debit decreases balance
                running_balance = running_balance + credit - debit

            ledger_rows.append(LedgerRow(
                number=entry_num,
                day=day,
                memo=f"Entry {entry_num} line on {line.account}", # Simplified memo for ledger row
                debit=debit,
                credit=credit,
                balance=running_balance
            ))

        return ledger_rows

    # Helper methods for balance/ledger
    def _is_descendant(self, ancestor_code: str, descendant_code: str) -> bool:
        """Checks if descendant_code is a descendant of ancestor_code (including self)."""
        if ancestor_code == descendant_code: return True
        try:
            account = self.chart.get(descendant_code)
            parent_code = account.parent
            while parent_code:
                if parent_code == ancestor_code:
                    return True
                try:
                    account = self.chart.get(parent_code)
                    parent_code = account.parent
                except KeyError:
                    # Should not happen in a valid chart
                    return False
        except KeyError:
            return False
        return False

    def _is_date_in_range(self, day: datetime.date, start: Optional[datetime.date], end: Optional[datetime.date]) -> bool:
        """Checks if day is within [start, end] inclusive."""
        if start and day < start:
            return False
        if end and day > end:
            return False
        return True

