def _calculate_period_balance(journal: Journal, code: str, start: Optional[date_type], end: Optional[date_type], is_debit_normal: bool) -> Decimal:
    # Reuses logic from Journal.balance but ensures only the final balance is returned for reporting context
    # For statements, we need the *net* balance contribution over the period.

    # In this simplified context, we iterate over relevant lines to sum contributions.
    # We must replicate the descendant logic here or rely on Journal's internal structure if exposed.

    try:
        account = journal.chart.get(code)
        descendant_codes = {code}
        queue = [account]
        while queue:
            current = queue.pop(0)
            for child in journal.chart.children(current.code):
                descendant_codes.add(child.code)
                queue.append(child)
    except KeyError: # Should not happen if called correctly
        return Decimal('0')

    total_debit_contribution = Decimal('0')
    total_credit_contribution = Decimal('0')

