@dataclass
class Headers:
    """An ordered, case-insensitive multi-map of header fields.
    """
    pairs: Tuple[Tuple[str, str], ...] = field(default_factory=tuple)

    def add(self, name: str, value: str):
        """Appends a field.
        """
        # Note: For simplicity and adherence to immutability/functional style common in such structures,
        # we assume this method would return a new Headers instance in a real implementation.
        # Here, we simulate the logic required for the definition.
        new_pairs = list(self.pairs) + [(name, value)]
        # In a real context, you'd replace self with a new instance or use a mutable internal structure.
        # For this static code generation, we focus on the interface.
        pass

    def set(self, name: str, value: str):
        """Replaces every field with that name by a single one.
        """
        original_pairs = list(self.pairs)
        try:
            # Find the first occurrence of the name (case-insensitive)
            first_index = next(i for i, (n, _) in enumerate(original_pairs) if n.lower() == name.lower())
            # Replace it
            new_pairs = original_pairs[:first_index] + [(name, value)] + original_pairs[first_index+1:]
        except StopIteration:
            # If not found, append it at the end
            new_pairs = list(original_pairs) + [(name, value)]

        # Again, simulating the required behavior for definition.
        pass

    def get(self, name: str, default: Optional[str] = None) -> Optional[str]:
        """Returns the first value for a header, case-insensitive.
        """
        for n, v in self.pairs:
            if n.lower() == name.lower():
                return v
        return default

    def __getitem__(self, name: str) -> str:
        """Raises KeyError if not found.
        """
        for n, v in self.pairs:
            if n.lower() == name.lower():
                return v
        raise KeyError(f"Header '{name}' not found")

    def get_all(self, name: str) -> List[str]:
        """Returns every value for a header in order.
        """
        values = []
        for n, v in self.pairs:
            if n.lower() == name.lower():
                values.append(v)
        return values

    def __contains__(self, name: str) -> bool:
        """Checks if a header exists (case-insensitive).
        """
        return any(n.lower() == name.lower() for n, _ in self.pairs)

    def __len__(self) -> int:
        """Returns the number of fields.
        """
        return len(self.pairs)

    def items(self) -> List[Tuple[str, str]]:
        """Returns all (name, value) pairs in order.
        """
        return list(self.pairs)


# --- Request --- 

@dataclass
class Request:
    """Represents an incoming HTTP request.
    """
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, Any] = field(default_factory=dict)
    state: Dict[str, Any] = field(default_factory=dict)

    @property
    def query(self) -> Dict[str, List[str]]:
        """Decodes the query string into a dict of lists.
        """
        if not self.query_string:
            return {}

        query_dict: Dict[str, List[str]] = {}
        parts = self.query_string.split('&')

        for part in parts:
            if not part:
                continue
            if '=' in part:
                name, value = part.split('=', 1)
            else:
                name = part
                value = ""

            # Decoding logic
            def decode_percent_escape(s: str) -> str:
                decoded = []
                i = 0
                while i < len(s):
                    char = s[i]
                    if char == '+':
                        decoded.append(' ') # '+' means space
                        i += 1
                        continue
                    if char == '%':
                        if i + 2 <= len(s):
                            hex_code = s[i+1:i+3]
                            try:
                                byte_val = bytes.fromhex(hex_code)
                                decoded.append(byte_val.decode('utf-8'))
                                i += 3
                                continue
                            except ValueError:
                                raise BadRequest(f"Invalid percent escape sequence: %{hex_code}")
                        else:
                            raise BadRequest("Incomplete percent escape sequence")
                    else:
                        decoded.append(char)
                        i += 1
                return "".join(decoded)

            try:
                decoded_name = decode_percent_escape(name)
                decoded_value = decode_percent_escape(value)
            except BadRequest as e:
                raise e
            except Exception as e:
                 # Catch other potential decoding issues if they aren't BadRequest
                 raise BadRequest(f"Error decoding query parameter: {e}")

            if decoded_name not in query_dict:
                query_dict[decoded_name] = []
            query_dict[decoded_name].append(decoded_value)

        return query_dict

    @property
    def content_type(self) -> Tuple[str, Dict[str, str]]:
        """Parses Content-Type header.
        """
        headers_list = self.headers.items()
        ctype_header = next((v for n, v in headers_list if n.lower() == 'content-type'), None)

        if not ctype_header:
            return ('', {}) # Default

        media_type = ctype_header.split(';')[0].strip().lower()
        params: Dict[str, str] = {}

        for part in ctype_header.split(';')[1:]: # Skip first part (media type)
            part = part.strip()
            if '=' in part:
                name, value = part.split('=', 1)
                name = name.strip().lower()
                value = value.strip().strip('"') # Strip surrounding quotes
                # First occurrence wins
                if name not in params:
                    params[name] = value

        return (media_type, params)

    def text(self, charset: Optional[str] = None) -> str:
        """Decodes the body as text.
        """
        if not self.body:
            return ""
        charset = charset if charset else self.content_type[1].get('charset') or 'utf-8'
        try:
            return self.body.decode(charset)
        except UnicodeDecodeError as e:
            raise BadRequest(f"Failed to decode body using {charset}: {e}")

    def json(self) -> Any:
        """Parses the body as JSON.
        """
        try:
            text = self.text()
            return json.loads(text)
        except (BadRequest, json.JSONDecodeError) as e:
            raise BadRequest(f"Failed to parse JSON body: {e}")


# --- Response ---

@dataclass
class Response:
    """Represents an outgoing HTTP response.
    """
    status: int = 200
    headers: Headers = field(default_factory=Headers)
    body: bytes = b''

    @classmethod
    def text(cls, s: str, status: int = 200) -> 'Response':
        """Creates a response with plain text content.
        """
        return cls(status=status, headers=Headers(), body=s.encode('utf-8') + b'\r\n', headers=Headers()) # Body must end in \r\n for standard compliance, though content-length handles it

    @classmethod
    def json(cls, obj: Any, status: int = 200) -> 'Response':
        """Creates a response with JSON content.
        """
        content = json.dumps(obj, separators=(',', ':'), sort_keys=True)
        return cls(status=status, headers=Headers(), body=content.encode('utf-8') + b'\r\n')

    def to_bytes(self) -> bytes:
        """Serialises the response into raw bytes.
        """
        lines: List[bytes] = []

        # 1. Status Line
        reason_map = {
            200: "OK", 201: "Created", 204: "No Content", 400: "Bad Request",
            401: "Unauthorized", 404: "Not Found", 405: "Method Not Allowed", 500: "Internal Server Error"
        }
        reason = reason_map.get(self.status, "Unknown")
        status_line = f"HTTP/1.1 {self.status} {reason}".encode('latin-1')
        lines.append(status_line)

        # 2. Headers
        # We need to ensure Content-Length is the LAST header.
        header_pairs = list(self.headers.items())
        cl_header = None

        for name, value in header_pairs:
            if name.lower() == "content-length":
                # Drop existing Content-Length header
                cl_header = None 
                continue
            lines.append(f"{name}: {value}".encode('latin-1'))

        # 3. Content-Length (must be last)
        content_length = len(self.body)
        lines.append(f"Content-Length: {content_length}".encode('latin-1'))

        # 4. Empty line separator
        lines.append(b"\r\n")

        # 5. Body
        # Note: If body includes trailing \r\n from Response.text/json, we might double it, 
        # but to_bytes should produce the raw byte sequence as requested.
        body_bytes = self.body

        return b"\r\n".join(lines) + b"\r\n" + body_bytes


# --- Parsing Request --- 

def parse_request(data: bytes) -> Request:
    """Parses exactly one request from raw bytes.
    """
    try:
        # Find the end of the header block (first \r\n\r\n)
        header_end_marker = b'\r\n\r\n'
        if header_end_marker not in data:
            raise BadRequest("Request missing body separator \r\n\r\n")

        header_bytes, body_bytes = data.split(header_end_marker, 1)

        # Decode headers using ISO-8859-1 as per spec
        header_lines = header_bytes.split(b'\r\n')

        # 1. Request Line
        request_line_bytes = header_lines[0].strip()
        if not request_line_bytes:
            raise BadRequest("Empty request line")

        try:
            request_line = request_line_bytes.decode('iso-8859-1').strip()
        except UnicodeDecodeError:
            raise BadRequest("Request line contains invalid ISO-8859-1 characters")

        parts = request_line.split(' ')
        if len(parts) != 3:
            raise BadRequest("Request line must be in format METHOD SP target SP version")

        method, target, version = parts
        if not (method.isupper() and method):
             raise BadRequest("Method must be one or more ASCII uppercase letters")
        if not target.startswith('/'):
            raise BadRequest("Target must start with /")
        if version not in ("HTTP/1.1", "HTTP/1.0"):
            raise BadRequest("Unsupported HTTP version")

        # 2. Headers
        raw_headers: Dict[str, str] = {}
        headers_list: List[Tuple[str, str]] = []

        for line_bytes in header_lines[1:]:
            line_bytes = line_bytes.strip()
            if not line_bytes:
                continue # Should not happen if split correctly, but defensive

            try:
                line = line_bytes.decode('iso-8859-1').strip()
            except UnicodeDecodeError:
                raise BadRequest("Header line contains invalid ISO-8859-1 characters")

            if line.startswith(' ') or line.startswith('\t'):
                raise BadRequest("Obsolete line folding found")

            if ':' not in line:
                 # Skip malformed lines if we expect Content-Length/Transfer-Encoding
                 # but based on spec, a header line MUST be name:value
                 raise BadRequest(f"Malformed header line: {line}")

            name, value = line.split(':', 1)
            name = name.strip()
            value = value.strip() # Remove surrounding spaces/tabs

            # Validate name characters (A–Z a–z 0–9 ! # $ % & ' * + - . ^ _ ` | ~)
            # Token characters defined in RFC 7230 Section 3.2.6 (simplified set)
            name_valid = re.fullmatch(r"[A-Za-z0-9!#$%&'*+.^_`|~-]+", name)
            if not name_valid:
                raise BadRequest(f"Invalid header name: {name}")

            headers_list.append((name, value))
            raw_headers[name.lower()] = value # Store for quick lookup

        # 3. Body Parsing (Content-Length vs Transfer-Encoding)
        body_len = 0
        transfer_encoding = raw_headers.get('transfer-encoding', '').lower()
        content_length_str = raw_headers.get('content-length')

        if transfer_encoding == 'chunked':
            # Chunked decoding logic
            chunked_body = b''
            remaining_body = body_bytes
            while True:
                # Read chunk size line (hex) followed by \r\n
                # Find the end of the size line (first \r\n)
                size_end = remaining_body.find(b'\r\n')
                if size_end == -1:
                    raise BadRequest("Incomplete chunked body stream")

                size_line = remaining_body[:size_end].decode('ascii').strip()

                try:
                    # Size can be followed by optional trailer info, but we only read the hex size
                    chunk_size = int(size_line, 16)
                except ValueError:
                    raise BadRequest(f"Invalid chunk size in chunked body: {size_line}")

                remaining_body = remaining_body[size_end + 2:]

                if chunk_size == 0:
                    # End of chunks. Check for trailers (ignored) and final empty line.
                    trailer_end = remaining_body.find(b'\r\n\r\n')
                    if trailer_end == -1:
                        raise BadRequest("Chunked body ended without final empty line (trailer/data separation)")
                    # Consume trailers and final CRLF
                    remaining_body = remaining_body[trailer_end + 4:]
                    break

                # Read the chunk data
                chunk_data_end = remaining_body.find(b'\r\n', 0)
                if chunk_data_end == -1:
                    raise BadRequest("Incomplete chunk data")

                chunk_data = remaining_body[:chunk_data_end]
                chunked_body += chunk_data
                remaining_body = remaining_body[chunk_data_end + 2:]

            body_bytes = chunked_body
            body_len = len(chunked_body)
        elif content_length_str:
            try:
                body_len = int(content_length_str)
            except ValueError:
                raise BadRequest("Content-Length must be decimal digits only")

            if len(body_bytes) != body_len:
                raise BadRequest(f"Body size mismatch: Expected {body_len}, got {len(body_bytes)}")
        else:
            # No headers, body is empty
            body_len = 0
            body_bytes = b''

        # Check for leftover bytes after body
        if len(body_bytes) != body_len:
             raise BadRequest("Bytes left over after body content")

        # 4. Request object creation

        # Path and Query String derivation
        path_parts = target.split('?', 1)
        path = path_parts[0]
        query_string = path_parts[1] if len(path_parts) > 1 else ""

        return Request(
            method=method,
            target=target,
            path=path,
            query_string=query_string,
            version=version,
            headers=Headers(pairs=headers_list),
            body=body_bytes,
            params={}, # Filled by router
            state={}
        )

    except HTTPError as e:
        # Re-raise specific HTTP errors caught during parsing
        raise e
    except Exception as e:
        # Catch any unexpected errors and map them to BadRequest if necessary
        if isinstance(e, BadRequest):
            raise e
        raise BadRequest(f"Parsing failed due to unexpected error: {e}")

from typing import Callable, Any, List, Tuple, Dict, Union, Optional
import re
from .request import Request, Response, HTTPError, BadRequest

# --- Exceptions defined in the specification ---

class NotFound(HTTPError):
    """404 Not Found exception."""
    def __init__(self):
        super().__init__(404, "Not Found")

class MethodNotAllowed(HTTPError):
    """405 Method Not Allowed exception."""
    def __init__(self, allowed: List[str]):
        super().__init__(405, "Method Not Allowed")
        self.allowed = sorted(allowed)

# Regex for path segment definition: literal | {name} | {name:int} | {name:path}
SEGMENT_REGEX = re.compile(r"^([a-zA-Z0-9_]+):([a-z]+)$")

class Router:
    """Router for mapping methods and paths to handlers."""
    def __init__(self):
        # Structure: {method: List[Tuple[pattern_compiled, handler, params_spec]]}
        self._routes: Dict[str, List[Tuple[re.Pattern, Callable, List[str]]]] = {}

    def add(self, method: str, pattern: str, handler: Callable) -> None:
        """Registers a handler for a specific HTTP method and path pattern."""
        if not pattern.startswith('/'):
            raise ValueError("Pattern must start with '/'.")

        # 1. Validate pattern structure and extract parameters
        path_segments = pattern.strip('/').split('/') if pattern != '/' else []
        params_spec_names = []

        try:
            # Check for repeated parameter names and structural validity
            for segment in path_segments:
                if segment.startswith('{') and segment.endswith('}'):
                    content = segment[1:-1]
                    if ':' in content:
                        name, converter = content.split(':', 1)
                        if name in params_spec_names: 
                            raise ValueError(f"Repeated parameter name '{name}' in pattern.")
                        if converter not in ('int', 'path'):
                            raise ValueError(f"Unknown converter: {converter}")
                        params_spec_names.append(name)
                    else: # Simple named segment
                        name = content
                        if name in params_spec_names: 
                            raise ValueError(f"Repeated parameter name '{name}' in pattern.")
                        params_spec_names.append(name)
                else:
                    # Literal segment
                    pass 

            # Check for 'path' converter usage
            has_path_param = any(s.endswith(':path}') for s in path_segments)
            if has_path_param and not path_segments[-1].endswith(':path}'):
                 raise ValueError("Path segment converter '{name:path}' must be the last segment.")

            # Regex construction
            regex_segment_map = {}

            for i, segment in enumerate(path_segments):
                if segment.startswith('{'):
                    content = segment[1:-1]
                    if ':' in content:
                        name, converter = content.split(':', 1)
                        if converter == 'int':
                            regex_segment_map[name] = r"[0-9]+"
                        elif converter == 'path':
                            # Path segment: matches everything until the end of the string
                            # Must ensure it's the last segment to match the required regex structure
                            regex_segment_map[name] = r".*"
                        else:
                            raise ValueError(f"Unknown converter: {converter}")
                    else: # Simple named segment
                        name = content
                        regex_segment_map[name] = r"[^/]+"
                else:
                    # Literal segment
                    regex_segment_map[segment] = re.escape(segment)

            # Reconstruct path segments into regex string
            # Note: This reconstruction assumes the regex captures groups in the order of path_segments.
            full_regex_path = r'/'.join([regex_segment_map[s] for s in path_segments])
            compiled_regex = re.compile(r'^' + full_regex_path + r'$')

        except ValueError as e:
            raise e
        except Exception:
            raise ValueError("Invalid pattern structure provided to Router.add.")

        # 2. Store the route
        method = method.upper()
        if method not in self._routes:
            self._routes[method] = []

        # Store: (compiled_regex, handler, list_of_param_names)
        self._routes[method].append((compiled_regex, handler, params_spec_names))

    def _decode_segment(self, segment: str) -> str: 
        # Segment decoding rule: percent-decode, but '+' stays '+'
        return re.sub(r'%([0-9a-fA-F]{2})', lambda m: chr(int(m.group(1), 16)), segment)

    def resolve(self, method: str, path: str) -> Tuple[Callable, Dict[str, Any]]:
        """Resolves the handler and parameters for a given method and path."""
        method = method.upper()

        # Helper to extract params from a match object based on path_segments
        def extract_params(match: re.Match, param_names: List[str]) -> Dict[str, Any]:
            params = {}
            # Parameters correspond to capture groups 1, 2, 3... in order of registration
            for i, name in enumerate(param_names):
                # Group index is i + 1
                value_raw = match.group(i + 1)
                # Basic decoding applied
                params[name] = self._decode_segment(value_raw)
            return params

        # 1. Attempt to find a match for the specific method
        if method in self._routes:
            for compiled_regex, handler, param_names in self._routes[method]:
                match = compiled_regex.match(path)
                if match:
                    return handler, extract_params(match, param_names)

        # 2. Check for HEAD fallback to GET
        if method == 'HEAD' and 'GET' in self._routes:
            for compiled_regex, handler, param_names in self._routes['GET']:
                match = compiled_regex.match(path)
                if match:
                    # HEAD served by GET handler
                    return handler, extract_params(match, param_names)

        # 3. Check for any path match to determine allowed methods
        matching_methods = set()
        for m, routes in self._routes.items():
            for compiled_regex, _, _ in routes:
                if compiled_regex.match(path):
                    matching_methods.add(m)

        if not matching_methods:
            raise NotFound()

        if method in matching_methods:
            # Should be unreachable if logic is sound, but safety return
            raise MethodNotAllowed(list(matching_methods))

        # If path matches but method does not
        raise MethodNotAllowed(list(matching_methods))

    def dispatch(self, request: Request) -> Response:
        """Resolves the request, executes the handler, and returns the Response."""
        handler, params = self.resolve(request.method, request.path)

        # Store parameters on the request object
        request.params = params

        # Call handler
        response = handler(request)

        # HEAD request handling: body must be empty, headers preserved
        if request.method == 'HEAD' and response.status != 204:
            response.body = b''

        return response

from typing import List, Callable, Dict, Any
import json
import base64

# Import necessary components from other modules
from .request import Request, Response, HTTPError, BadRequest
from .router import Router, NotFound, MethodNotAllowed

# Define the type for a middleware function
# It takes a request, and a function to call the next layer in the chain
Middleware = Callable[[Request, Callable[[Request], Response]], Response]

class App:
    """The application container that manages middleware and routing.
    """
    def __init__(self, router: Router, middleware: List[Middleware] = ()): 
        self.router = router
        self.middleware = middleware

    def _handle_error(self, error: HTTPError, original_exception: Exception = None) -> Response:
        """Converts an HTTPError or any other exception into a standard Response.
        """
        status = getattr(error, 'status', 500)
        reason = getattr(error, 'reason', 'Internal Server Error')

        if status >= 400 and status < 500 and isinstance(error, MethodNotAllowed):
            # Specific handling for MethodNotAllowed
            response = Response(status=status, headers=dict())
            response.headers.add("Allow", ', '.join(error.allowed))
            return response

        # Default error response handling
        response = Response(status=status, headers={})

        # For errors originating from HTTPError or exceptions, format the body.
        if isinstance(error, HTTPError) or isinstance(original_exception, HTTPError):
             # HTTPError derived exceptions (like NotFound, BadRequest) have status/reason
             response.headers.add("Content-Type", "text/plain; charset=utf-8")
             response.body = f"{status} {reason}".encode('utf-8')
        else:
            # Catch-all for unexpected exceptions (500)
            response.body = f"500 Internal Server Error".encode('utf-8')

        return response

    def handle(self, request: Request) -> Response:
        """Runs the middleware chain, terminating at the router.
        """

        def call_next(req: Request) -> Response:
            try:
                # Innermost call: Router dispatch
                return self.router.dispatch(req)
            except HTTPError as e:
                # Router/Request layer throws a known HTTP error
                return self._handle_error(e)
            except Exception as e:
                # Catch all other exceptions and convert to 500
                return self._handle_error(e, original_exception=e)

        # Execute middleware chain in order (first is outermost)
        # The first middleware in the list is outermost
        current_response = request
        for mw in self.middleware:
            # The middleware is responsible for calling the next one in the chain
            next_chain = lambda r: mw(r, call_next)
            # We need to chain them such that the final call_next wraps everything.
            # We build the chain backwards conceptually, but execute forwards.
            pass # This simple loop structure is tricky with the call_next definition above.

        # Rebuilding the chain execution structure for clarity:
        def chain_runner(req: Request) -> Response:
            # Start with the innermost function (router dispatch)
            def innermost(r: Request) -> Response:
                try:
                    return self.router.dispatch(r)
                except HTTPError as e:
                    return self._handle_error(e)
                except Exception as e:
                    return self._handle_error(e, original_exception=e)

            # Wrap outwards using the provided middleware list
            chain = innermost
            for mw in self.middleware:
                # Create a new callable that wraps the existing chain
                next_chain = chain
                chain = lambda r, next_c=next_chain, current_mw=mw: current_mw(r, next_c)

            # Execute the outermost chain wrapper
            return chain(req)

        return chain_runner(request)

    def handle_bytes(self, data: bytes) -> bytes:
        """Parses raw bytes, handles request, and returns serialized response bytes.
        """
        try:
            # 1. Parse request
            request = parse_request(data)
        except BadRequest as e:
            # Parsing failed, return immediate 400 error response without middleware
            response = Response(400, headers={})
            response.headers.add("Content-Type", "text/plain; charset=utf-8")
            response.body = f"400 Bad Request".encode('utf-8')
            return response.to_bytes()

        # 2. Handle through middleware/router
        response = self.handle(request)

        # 3. Serialize response
        return response.to_bytes() if hasattr(response, 'to_bytes') else b''


# --- Middleware Factories ---

def logger(lines: List[str]) -> Middleware:
    """Middleware that logs request details after the response is generated.
    """
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        response = call_next(request)

        # Log the event
        status = getattr(response, 'status', 500)
        log_line = f"{request.method} {request.path} {status}"
        lines.append(log_line)
        return response
    return mw


def cookies() -> Middleware:
    """Middleware that parses the Cookie header into request.state['cookies'].
    """
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        cookies_dict: Dict[str, str] = {}
        cookie_header = request.headers.get("Cookie")

        if cookie_header:
            cookie_pairs = cookie_header.split(";")
            for piece in cookie_pairs:
                piece = piece.strip()
                if not piece: continue

                # Treat like Content-Type parsing for value extraction, but names keep case.
                if '=' in piece:
                    name, value = piece.split('=', 1)
                    name = name.strip()
                    # Strip surrounding quotes, if present
                    value = value.strip().strip('"')
                    # First occurrence wins
                    if name not in cookies_dict:
                         cookies_dict[name] = value
                # Pieces without '=' are skipped

        request.state['cookies'] = cookies_dict
        return call_next(request)
    return mw


def basic_auth(users: Dict[str, str], realm: str = 'app') -> Middleware:
    """Middleware for basic HTTP authentication.
    """
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        auth_header = request.headers.get("Authorization")

        if not auth_header or not auth_header.startswith("Basic "): 
            # No authorization header, proceed to next layer
            return call_next(request)

        auth_string = auth_header[6:] # Remove "Basic "

        try:
            # Base64 decode the string
            decoded_bytes = base64.b64decode(auth_string)
            decoded_str = decoded_bytes.decode('utf-8').strip()

            # Split at the first colon
            if ':' not in decoded_str:
                raise ValueError("Invalid Basic Auth format")

            user, password = decoded_str.split(':', 1)

            if user in users and users[user] == password:
                # Authentication successful
                request.state['user'] = user
                return call_next(request)
            else:
                # User not found or password incorrect
                response = Response(401, headers={})
                response.headers.add("WWW-Authenticate", f"Basic realm=\"{realm}\"")
                return response
        except (ValueError, base64.binascii.Error):
            # Decoding or format error
            response = Response(401, headers={})
            response.headers.add("WWW-Authenticate", f"Basic realm=\"{realm}\"")
            return response

    return mw

class KVError(Exception):
    """Base exception for the kv package."""
    pass

class CorruptLog(KVError):
    """Raised when the write-ahead log is corrupted."""
    def __init__(self, message: str, offset: int):
        super().__init__(message)
        self.offset = offset

class CorruptSnapshot(KVError):
    """Raised when the snapshot file is corrupted."""
    pass

