        """Handles addition and subtraction (lowest precedence)"""
        node = self.term()

        while self.current_token().type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            right = self.term()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def term(self) -> FormulaNode:
        """Handles multiplication and division (medium precedence)"""
        node = self.unary()

        while self.current_token().type in ('MUL', 'DIV'):
            op_token = self.consume()
            right = self.unary()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def unary(self) -> FormulaNode:
        """Handles unary signs, numbers, references, or parenthesized expressions (highest precedence)"""
        token = self.current_token()

        if token.type == 'MINUS' or token.type == 'PLUS':
            op_token = self.consume()
            operand = self.unary() # Unary operators bind tightly to the next term
            return UnaryOpNode(op_token.value, operand)

        elif token.type == 'NUMBER':
            self.consume('NUMBER')
            try:
                value_str = token.value
                if '.' in value_str:
                    return NumberNode(float(value_str))
                else:
                    return NumberNode(int(value_str))
            except ValueError:
                # Should be caught by tokenizer, but as safety net
                raise FormulaError("Invalid number format")

        elif token.type == 'REF':
            ref_token = self.consume('REF')
            # Validate reference immediately upon parsing
            if not is_valid_reference(ref_token.value):
                 raise FormulaError(f"Invalid cell reference: {ref_token.value}")
            return RefNode(ref_token.value)

        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            expr_node = self.expression()
            self.consume('RPAREN')
            return ParenthesizedExprNode(expr_node)

        else:
            raise FormulaError(f"Unexpected token while parsing unary expression: {token.type} ({token.value})")


