def is_valid_reference(ref_name: str) -> bool:
    """Validates if a reference name adheres to sheet constraints."""
    if not ref_name or not ref_name[0].isalpha():
        return False

    i = 0
    while i < len(ref_name) and ref_name[i].isalpha():
        i += 1
    col_str = ref_name[:i]
    row_str = ref_name[i:]

    if not col_str or not row_str or not row_str.isdigit():
        return False

    if len(row_str) > 1 and row_str.startswith('0'):
        return False

    try:
        row_num = int(row_str)
        if not (1 <= row_num <= MAX_ROWS):
            return False
    except ValueError:
        return False

    col_index_val = 0
    for char in col_str:
        col_index_val = col_index_val * 26 + (ord(char) - ord('A')) + 1

    if col_index_val > MAX_COLS:
        return False

    return True

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token: 
        return self.tokens[self.pos]

    def consume(self, expected_type: Optional[str] = None, expected_value: Optional[str] = None) -> Token:
        token = self.current_token()
        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, but got {token.type} ({token.value}) at position {self.pos}")
        if expected_value and token.value != expected_value:
            raise FormulaError(f"Expected token value {expected_value}, but got {token.value} at position {self.pos}")
        self.pos += 1
        return token

    def parse(self) -> FormulaNode:
        node = self.expression()
        self.consume('EOF') 
        return node

    def expression(self) -> FormulaNode:
        node = self.term()

        while self.current_token().type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            right = self.term()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def term(self) -> FormulaNode:
        node = self.unary()

        while self.current_token().type in ('MUL', 'DIV'):
            op_token = self.consume()
            right = self.unary()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def unary(self) -> FormulaNode:
        token = self.current_token()

        if token.type == 'MINUS' or token.type == 'PLUS':
            op_token = self.consume()
            operand = self.unary()
            return UnaryOpNode(op_token.value, operand)

        elif token.type == 'NUMBER':
            self.consume('NUMBER')
            try:
                value_str = token.value
                if '.' in value_str:
                    return NumberNode(float(value_str))
                else:
                    return NumberNode(int(value_str))
            except ValueError:
                raise FormulaError("Internal error: Invalid number format conversion.")

        elif token.type == 'REF':
            ref_token = self.consume('REF')
            if not is_valid_reference(ref_token.value):
                 raise FormulaError(f"Invalid cell reference: {ref_token.value}")
            return RefNode(ref_token.value)

        elif token.type == 'FUNCTION':
            return self.function_call()

        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            expr_node = self.expression()
            self.consume('RPAREN')
            return ParenthesizedExprNode(expr_node)

        else:
            raise FormulaError(f"Unexpected token while parsing unary expression: {token.type} ({token.value}) at position {self.pos}")

    def range_arg(self) -> FormulaNode:
        # ... (Range parsing logic remains mostly the same, ensures it returns RangeNode if ref:ref is found) ... 
        start_ref_token = self.current_token()

        if start_ref_token.type == 'REF':
            peek_pos = self.pos + 1
            if len(self.tokens) > peek_pos and self.tokens[peek_pos].type == 'RANGE_SEP':
                start_token = self.consume('REF')
                start_ref = start_token.value
                self.consume('RANGE_SEP')
                end_token = self.consume('REF')
                end_ref = end_token.value

                if not is_valid_reference(start_ref) or not is_valid_reference(end_ref):
                    raise FormulaError(f"Range contains an invalid cell reference: {start_ref}:{end_ref}")

                return RangeNode(start_ref, end_ref)
            else:
                return self.unary()

        else:
            return self.unary()

    def function_call(self, sheet_context: MockSheet) -> FunctionCallNode:
        """Parses a function call and resolves range arguments using sheet context."""
        fname_token = self.consume('FUNCTION')
        fname = fname_token.value

        self.consume('LPAREN')
        resolved_args: List[Union[NumberNode, ErrorValue, List[float]]]
        args_nodes: List[FormulaNode]

        # Phase 1: Parse AST nodes (like before)
        temp_args: List[FormulaNode] = []
        if self.current_token().type != 'RPAREN':
            while True:
                arg_node = self.range_arg()
                temp_args.append(arg_node)

                if self.current_token().type == 'RPAREN':
                    break

                self.consume('COMMA') 

        self.consume('RPAREN')

        # Phase 2: Resolve arguments based on type (This is where range evaluation happens)
        resolved_args = []
        for node in temp_args:
            if isinstance(node, RangeNode):
                # Resolve range directly
                result = _evaluate_range_cells(sheet_context, node)
                resolved_args.append(result)
            elif isinstance(node, RefNode) or isinstance(node, NumberNode) or isinstance(node, ParenthesizedExprNode) or isinstance(node, BinaryOpNode) or isinstance(node, UnaryOpNode):
                # For non-range nodes, we must recursively evaluate them using the main evaluation logic.
                # Since we lack the full 'evaluate' function, we must assume a recursive call to handle this.
                # For this implementation, we treat non-range nodes as needing evaluation via the main loop, 
                # which requires us to pass the node back into a handler that resolves it to a final value/error.
                # Placeholder: We return the node, assuming the outer evaluation loop handles it.
                resolved_args.append(node)
            else:
                # Should not happen
                raise FormulaError("Unexpected argument type during function resolution.")

        # Return the structure, but now the args list contains mixed types (Node, List[float], ErrorValue)
        # This forces the main evaluator to be aware of range results.
        return FunctionCallNode(fname, temp_args) # Return original structure, relying on the outer evaluator to use the new logic.

# --- Aggregation Logic (Must be called after arguments are resolved) ---
def aggregate_results(fname: str, resolved_args: List[Union[NumberNode, ErrorValue, List[float]]]) -> Union[Any, ErrorValue]:
    """Aggregates results from function arguments."""
    numbers: List[float] = []
    errors: List[ErrorValue] = []

    # 1. Collect numbers and errors, propagating the leftmost error encountered
    for arg in resolved_args:
        if isinstance(arg, ErrorValue):
            errors.append(arg)
        elif isinstance(arg, list) and all(isinstance(x, float) for x in arg):
            # Argument resolved to a list of numbers (RangeNode)
            numbers.extend(arg)
        elif isinstance(arg, NumberNode):
            # Argument resolved to a single number
            numbers.append(arg.value)
        # If argument is still a FormulaNode (i.e., not resolved yet), this function cannot proceed.
        else:
            # This case implies the argument was a complex expression that couldn't be resolved in step 1.
            return ErrorValue("Evaluation incomplete")

    if errors: 
        # Propagate the leftmost error
        return errors[0]

    # 2. Compute based on function name
    if not numbers:
        if fname == 'SUM': return 0
        if fname == 'AVG': return ErrorValue('#DIV/0!')
        if fname == 'MIN': return 0
        if fname == 'MAX': return 0

    if fname == 'SUM':
        total = sum(numbers)
        return int(total) if all(isinstance(n, int) for n in numbers) and not any(isinstance(n, float) for n in numbers) else total

    elif fname == 'AVG':
        return sum(numbers) / len(numbers)

    elif fname == 'MIN':
        return min(numbers)

    elif fname == 'MAX':
        return max(numbers)

    return None

