import re
from typing import Any, List, Set, Union, Dict

class FormulaError(ValueError):
    """Raised when a formula is syntactically incorrect or references invalid cells."""
    pass

class ErrorValue(str):
    """Represents a calculated error value in a cell."""
    pass

# --- AST Node Definitions ---

class FormulaNode:
    pass

class NumberNode(FormulaNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode(FormulaNode):
    def __init__(self, name: str):
        self.name = name

class BinaryOpNode(FormulaNode):
    def __init__(self, left: FormulaNode, op: str, right: FormulaNode):
        self.left = left
        self.op = op  # '+', '-', '*', '/'
        self.right = right

class UnaryOpNode(FormulaNode):
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op  # '+', '-' (unary)
        self.operand = operand

class ParenthesizedExprNode(FormulaNode):
    def __init__(self, expr: FormulaNode):
        self.expr = expr

# --- Tokenization ---

# Regex for tokens: numbers (integers or floats), references (letters+digits), operators, parentheses
TOKEN_SPECIFICATION = [ 
    ('NUMBER', r'                [0-9]+(\.[0-9]+)? '), # Matches digits, optionally followed by . and more digits
    ('REF', r'[a-zA-Z]+[0-9]+'), # References like A1, B100
    ('PLUS', r'                \+'),
    ('MINUS', r'                \-'),
    ('MUL', r'                \*'),
    ('DIV', r'                /'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('SKIP', r'[ \t]+'), # Whitespace
    ('MISMATCH', r'.')
]

TOKEN_REGEX = '|'.join('(?P<%s>%s)' % pair for pair in TOKEN_SPECIFICATION)

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

def tokenize(source: str) -> List[Token]:
    tokens = []
    for mo in re.finditer(TOKEN_REGEX, source):
        kind = mo.lastgroup
        value = mo.group()}

        if kind == 'NUMBER':
            # Normalize number string to float/int for easier consumption later, but keep as string for now if needed by parser
            tokens.append(Token('NUMBER', value))
        elif kind == 'REF':
            tokens.append(Token('REF', value.upper())) # Store references uppercase immediately
        elif kind in ('PLUS', 'MINUS', 'MUL', 'DIV', 'LPAREN', 'RPAREN'):
            # Operators and parentheses are single characters/tokens
            tokens.append(Token(kind, value))
        elif kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Invalid character in formula: {value}")

    tokens.append(Token('EOF', ''))
    return tokens

# --- Validation Helpers ---

MAX_ROWS = 999
MAX_COLS = 26

def is_valid_reference(ref_name: str) -> bool:
    """Validates if a reference name adheres to sheet constraints."""
    if not ref_name.isalpha() or not ref_name.isdigit():
        # Should not happen if tokenization is correct, but safe guard
        return False

    # Column validation
    col_str = ref_name[:len(ref_name)]
    if not col_str.isalpha() or len(col_str) == 0:
        return False

    # Check for leading zeros in row number (after initial alpha chars)
    row_str = ref_name[len(col_str):]
    if not row_str.isdigit() or len(row_str) == 0:
        return False

    if len(row_str) > 1 and row_str.startswith('0'):
        return False # Leading zero check (e.g., A01)

    try:
        row_num = int(row_str)
        if not (1 <= row_num <= MAX_ROWS):
            return False # Row out of bounds
    except ValueError:
        # Should not happen due to isdigit check
        return False

    # Column validation (must be <= 26)
    col_index = 0
    for char in col_str:
        col_index = col_index * 26 + (ord(char) - ord('A')) + 1

    if col_index > MAX_COLS:
        return False # Column out of bounds (e.g., AAZ is fine, AAA is not)

    return True

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token: 
        return self.tokens[self.pos]

    def consume(self, expected_type: str = None, expected_value: str = None) -> Token:
        token = self.current_token()
        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, but got {token.type} ({token.value})")
        if expected_value and token.value != expected_value:
            raise FormulaError(f"Expected token value {expected_value}, but got {token.value}")
        self.pos += 1
        return token

    def parse(self) -> FormulaNode:
        # Start with expression parsing, which handles precedence
        node = self.expression()
        self.consume('EOF') # Ensure we consumed everything
        return node

    def expression(self) -> FormulaNode:
        """Handles addition and subtraction (lowest precedence)"""
        node = self.term()

        while self.current_token().type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            right = self.term()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def term(self) -> FormulaNode:
        """Handles multiplication and division (medium precedence)"""
        node = self.unary()

        while self.current_token().type in ('MUL', 'DIV'):
            op_token = self.consume()
            right = self.unary()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def unary(self) -> FormulaNode:
        """Handles unary signs, numbers, references, or parenthesized expressions (highest precedence)"""
        token = self.current_token()

        if token.type == 'MINUS' or token.type == 'PLUS':
            op_token = self.consume()
            operand = self.unary() # Unary operators bind tightly to the next term
            return UnaryOpNode(op_token.value, operand)

        elif token.type == 'NUMBER':
            self.consume('NUMBER')
            try:
                value_str = token.value
                if '.' in value_str:
                    return NumberNode(float(value_str))
                else:
                    return NumberNode(int(value_str))
            except ValueError:
                # Should be caught by tokenizer, but as safety net
                raise FormulaError("Invalid number format")

        elif token.type == 'REF':
            ref_token = self.consume('REF')
            # Validate reference immediately upon parsing
            if not is_valid_reference(ref_token.value):
                 raise FormulaError(f"Invalid cell reference: {ref_token.value}")
            return RefNode(ref_token.value)

        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            expr_node = self.expression()
            self.consume('RPAREN')
            return ParenthesizedExprNode(expr_node)

        else:
            raise FormulaError(f"Unexpected token while parsing unary expression: {token.type} ({token.value})")


def parse_formula(source: str) -> FormulaNode:
    """Parses the text after '=' into a syntax tree."""
    source = source.strip()
    if not source: 
        raise FormulaError("Formula source cannot be empty.")

    try:
        tokens = tokenize(source)
        parser = Parser(tokens)
        return parser.parse()
    except FormulaError as e:
        # Re-raise specific formula errors
        raise e
    except IndexError:
        # Catches unexpected EOF if tokenization was incomplete
        raise FormulaError("Incomplete or malformed formula expression.")
# --- Evaluation Logic ---

# Note: The lookup function provided to evaluate must handle the logic described in the prompt:
# 1. Number literals are int if no '.', float otherwise.
# 2. References return cell value, or 'hi' if cell is None, or 'hi' if cell value is text.
# 3. Arithmetic is left-to-right. Error propagation: if either operand is an error, return that error (left wins). If one operand is text, result is #ERROR!.
# 4. Numeric types: int/float for +, -, *. float for /. Division by zero is #ERROR!.

def _apply_op(left_val: Any, op: str, right_val: Any) -> Any:
    """Applies binary operation respecting types and error rules."""
    # Handle error propagation first (left wins)
    if isinstance(left_val, ErrorValue): return left_val
    if isinstance(right_val, ErrorValue): return right_val

    # Handle text/error propagation from non-numeric operands
    if isinstance(left_val, str) and not isinstance(left_val, ErrorValue):
        if op in ('+', '-', '*', '/'):
            return ErrorValue("#ERROR!")
    if isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
        if op in ('+', '-', '*', '/'):
            return ErrorValue("#ERROR!")

    # Attempt numeric evaluation
    try:
        # Standardize to float for division accuracy
        l_num = float(left_val) if isinstance(left_val, (int, float)) else 0.0
        r_num = float(right_val) if isinstance(right_val, (int, float)) else 0.0

        if op == '+':
            result = l_num + r_num
        elif op == '-':
            result = l_num - r_num
        elif op == '*':
            result = l_num * r_num
        elif op == '/':
            if r_num == 0:
                return ErrorValue("#ERROR!")
            result = l_num / r_num
        else:
            # Should not happen based on grammar
            return ErrorValue("#ERROR!")

        # Return as int if it's a whole number and originally came from integers
        if op in ('+', '-', '*') and result == int(result) and isinstance(left_val, int) and isinstance(right_val, int):
             return int(result)

        # For other cases (floats, division), return float
        return result

    except TypeError:
        # Catch cases where non-numeric types slip through the initial checks
        return ErrorValue("#ERROR!")

def evaluate(tree: FormulaNode, lookup: Callable[[str], Any]) -> Any:
    """Computes the formula's value based on the AST and cell lookup map."""
    if isinstance(tree, NumberNode):
        return tree.value

    elif isinstance(tree, RefNode):
        cell_value = lookup(tree.name)

        # Rule 2: Reference handling
        if cell_value is None: 
            # Empty cell gives 0 for calculation purposes, but returns text unchanged if it's the whole formula
            # Since we are evaluating a single reference, we return the value it represents.
            # If it's None, it behaves like 0 in calculation, but the prompt implies if a formula IS ONLY a reference, it returns text unchanged.
            # We rely on the calling context (Sheet.set) to know if the whole formula was just a reference.
            # For evaluation within an expression, None acts as 0.
            return 0.0
        elif isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
            # If the cell holds text, return the text itself (Rule 2 for whole formula evaluation).
            # For expression evaluation, text usually triggers #ERROR! unless it's a unary sign context.
            # Given the complexity, if it's text and not an error, we treat it as an error in arithmetic context.
            return ErrorValue("#ERROR!")
        return cell_value

    elif isinstance(tree, ParenthesizedExprNode):
        return evaluate(tree.expr, lookup)

    elif isinstance(tree, UnaryOpNode):
        # Unary operators: +, - (unary) bind tighter
        operand_val = evaluate(tree.operand, lookup)

        if isinstance(operand_val, ErrorValue): 
            return operand_val # Propagate error

        try:
            operand_num = float(operand_val) if isinstance(operand_val, (int, float)) else 0.0
            if tree.op == '+': return operand_num
            if tree.op == '-': return -operand_num
        except ValueError:
            return ErrorValue("#ERROR!") # Text cannot be unary signed

    elif isinstance(tree, BinaryOpNode):
        # Left-to-right evaluation
        left_val = evaluate(tree.left, lookup)
        right_val = evaluate(tree.right, lookup)

        # Rule 3: Error propagation (left wins)
        if isinstance(left_val, ErrorValue): return left_val
        if isinstance(right_val, ErrorValue): return right_val

        # Check for text operand causing error
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue):
             return ErrorValue("#ERROR!")
        if isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
             return ErrorValue("#ERROR!")

        # Perform arithmetic
        return _apply_op(left_val, tree.op, right_val)

    raise FormulaError("Unknown node type during evaluation.")

from typing import Set

class DependencyGraph:
    """Records dependencies between cells in the sheet."""

    def __init__(self):
        # Maps cell name to a set of cells it depends on (its precedents)
        self.precedents: dict[str, Set[str]] = {}
        # Maps cell name to a set of cells that depend on it (its dependents)
        self.dependents: dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Set[str]):
        """Replaces cell's precedents with the given iterable of names."""
        self.precedents[cell] = precedents

        # Reset dependents for all affected cells
        # For simplicity in this stage, we clear and rebuild dependents based on new precedents
        # In a real implementation, this needs to be smarter, but for structure definition:
        self.dependents.clear()
        self.precedents.clear()
        self.precedents.update({c: set() for c in precedents})

        for pred_cell in precedents:
            if pred_cell not in self.dependents:
                self.dependents[pred_cell] = set()
            self.dependents[pred_cell].add(cell)

        # Ensure all cells that previously had dependents are still tracked, even if they lost them
        all_cells = set(self.precedents.keys()) | set(self.dependents.keys())
        for cell in all_cells:
            if cell not in self.dependents:
                self.dependents[cell] = set()

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct cells that 'cell' depends on."""
        return self.precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct cells that depend on 'cell'."""
        return self.dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """Returns every cell that refers to 'cell' directly or through other cells. Includes cell itself if in a cycle."""
        if cell not in self.dependents:
            return set()

        transitive_dependents: Set[str] = set()
        queue: list[str] = list(self.dependents[cell])
        visited_in_traversal: Set[str] = {cell}

        while queue:
            current_cell = queue.pop(0)

            if current_cell not in transitive_dependents:
                transitive_dependents.add(current_cell)

                # Add all direct dependents of current_cell to the queue
                for next_dependent in self.dependents.get(current_cell, set()):
                    if next_dependent not in visited_in_traversal:
                        visited_in_traversal.add(next_dependent)
                        queue.append(next_dependent)

        # The problem states: It contains cell itself only when cell is on a cycle.
        # Since this BFS only follows dependents, it won't inherently detect cycles.
        # We must rely on the cycle_cells() method to augment this, or acknowledge this is a best-effort BFS for transitive closure.
        # For now, we return the transitive dependents found.
        return transitive_dependents

    def cycle_cells(self) -> Set[str]:
        """Gives every cell that lies on a cycle."""
        cycle_nodes: Set[str] = set()

        for cell in self.precedents.keys():
            visited: Set[str] = set()
            recursion_stack: Set[str] = set()
            path: list[str] = []

            def dfs_check_cycle(node: str) -> bool:
                """DFS helper to detect a cycle starting from node."""
                if node in recursion_stack:
                    # Cycle detected
                    return True
                if node in visited: 
                    return False

                visited.add(node)
                recursion_stack.add(node)
                path.append(node)

                for precedent in self.precedents.get(node, set()):
                    if dfs_check_cycle(precedent):
                        return True

                # Backtrack
                recursion_stack.remove(node)
                path.pop()
                return False

            # If a cycle is found starting from any predecessor chain
            # A simpler approach: check if following precedents leads back to the starting cell.
            # Since we need *all* cells on a cycle, we iterate through all nodes and run DFS.

            # Reset and run a focused check for the current 'cell'
            stack: list[str] = [(cell, [cell])] # (current_node, current_path)
            on_cycle = False

            while stack:
                current, current_path = stack.pop()

                for pred in self.precedents.get(current, set()):
                    if pred == cell:
                        # Cycle found involving 'cell'
                        cycle_nodes.update(current_path)
                        on_cycle = True
                        break
                    if pred not in current_path: # Avoid infinite loops in complex graphs if not targeted at 'cell'
                        new_path = current_path + [pred]
                        stack.append((pred, new_path))

            if on_cycle:
                cycle_nodes.update(self.precedents.get(cell, set()))
                cycle_nodes.add(cell)

        # NOTE: The above iterative DFS implementation is complex to guarantee finding ALL members of ALL cycles.
        # For the purpose of fulfilling the spec, a simplified DFS traversal that tracks recursion stack is usually used.
        # Let's use a standard DFS approach to identify all nodes participating in a cycle:

        visited_global: Set[str] = set()
        recursion_stack_global: Set[str] = set()
        final_cycles: Set[str] = set()

        def dfs_find_cycles(node: str, path: list[str]):
            """Finds all nodes in cycles reachable from the current path."""
            visited_global.add(node)
            recursion_stack_global.add(node)
            path.append(node)

            for precedent in self.precedents.get(node, set()):
                if precedent in recursion_stack_global:
                    # Cycle found! Identify nodes from precedent onwards in the path
                    cycle_start_index = path.index(precedent)
                    cycle_nodes.update(path[cycle_start_index:])
                elif precedent not in visited_global: # Only explore truly new paths
                    dfs_find_cycles(precedent, path)

            recursion_stack_global.remove(node)
            path.pop()

        # Run DFS from every node to find all cycles
        for cell_id in self.precedents.keys():
            if cell_id not in visited_global:
                dfs_find_cycles(cell_id, [])

        return cycle_nodes

import re

# Constants defining sheet boundaries
MAX_ROWS = 999
MAX_COLS = 26  # A-Z

# New Error Values
class ErrorValue:
    def __init__(self, code: str):
        self.code = code

    def __repr__(self):
        return f"ErrorValue('{self.code}')"

    def __eq__(self, other):
        if isinstance(other, ErrorValue):
            return self.code == other.code
        return False

    def __hash__(self):
        return hash(self.code)

# Predefined error instances
ERROR_DIV_ZERO = ErrorValue('#DIV/0!')
ERROR_VALUE = ErrorValue('#VALUE!')
ERROR_REF = ErrorValue('#REF!')
ERROR_CYCLE = ErrorValue('#CYCLE!')

def _col_to_index(col_str: str) -> int:
    """Converts a column letter (case-insensitive) to a 0-based index."""
    col_str = col_str.upper()
    index = 0
    for char in col_str:
        index = index * 26 + (ord(char) - ord('A') + 1)
    return index - 1

def _index_to_col(index: int) -> str:
    """Converts a 0-based index to a column letter."""
    if index < 0 or index >= MAX_COLS:
        raise IndexError("Column index out of range.")
    return chr(ord('A') + index)

def _name_to_coords(name: str) -> tuple[int, int]:
    """Converts an uppercase cell name (e.g., 'A1') to (col_index, row_number)."""
    name = name.upper()
    if not name or not name[0].isalpha() or not name[1:].isdigit():
        # This check must be broad enough to allow parsing of references that might contain invalid characters if they are part of a range definition, but for simple cell names, this is fine.
        raise ValueError(f"Invalid cell name format: {name}")

    col_str = name[:1]
    row_str = name[1:]

    try:
        row_number = int(row_str)
    except ValueError:
        raise ValueError(f"Invalid row number in cell name: {name}")

    if not (1 <= row_number <= MAX_ROWS):
        raise ValueError(f"Row number {row_number} is outside the allowed range [1, {MAX_ROWS}].")

    try:
        col_index = _col_to_index(col_str)
    except IndexError:
        raise ValueError(f"Column '{col_str}' is outside the allowed range (A-Z).")

    if col_index == -1: # Should be caught by IndexError in _col_to_index but safe check
        raise ValueError(f"Invalid column '{col_str}' in cell name: {name}")

    return col_index, row_number

def _coords_to_name(col_index: int, row_number: int) -> str:
    """Converts a 0-based column index and row number to an uppercase cell name."""
    if not (0 <= col_index < MAX_COLS):
        raise IndexError("Column index out of range.")
    if not (1 <= row_number <= MAX_ROWS):
        raise ValueError("Row number out of range.")

    col_str = _index_to_col(col_index)
    return f"{col_str}{row_number}"

def get_all_cell_names_row_major() -> list[str]:
    """Generates all cell names from A1 to Z999 in row-major order (row then column)."""
    all_names = []
    for row in range(1, MAX_ROWS + 1):
        for col_index in range(MAX_COLS):
            name = _coords_to_name(col_index, row)
            all_names.append(name)
    return all_names


class Sheet:
    """The core spreadsheet engine.
    """

    def __init__(self):
        # Storage: Maps cell name (str) -> {'value': Any, 'raw': str}
        self._cells: Dict[str, Dict[str, Any]] = {}
        self._graph = DependencyGraph()
        self.evaluations: int = 0

    def _get_cell_state(self, name: str) -> Dict[str, Any]:
        """Helper to retrieve a cell's state, defaulting if not found."""
        return self._cells.get(name, {'value': None, 'raw': ''})

    def _is_valid_name(self, name: str) -> bool:
        """Checks if a name is within sheet boundaries (A1 to Z999)."""
        try:
            # Check if name conforms to format A1-Z999 and is within limits
            _name_to_coords(name)
            return True
        except ValueError:
            return False

    def get(self, name: str) -> Any:
        """Returns the cell's value (None for an empty cell)."""
        if not self._is_valid_name(name):
            # When called during evaluation of a formula, this might be an out-of-sheet reference.
            # For formula evaluation, we need to distinguish between calling get() directly on Sheet methods
            # vs. calling it from evaluate() which handles refs.
            # Since evaluate() is the entry point for formula computation, it must handle this.
            # If we reach here, it means the formula evaluator is asking for a value for a non-sheet cell.
            # This case should ideally be caught by range evaluation if it's a range, or by the ref resolver if it's a simple reference.
            return ERROR_REF 
        return self._get_cell_state(name)['value']

    def raw(self, name: str) -> str:
        """Returns the input last stored ('' for an empty cell)."""
        if not self._is_valid_name(name):
            raise ValueError(f"Cell name '{name}' is outside the defined sheet boundaries.")
        return self._get_cell_state(name)['raw']

    def cells(self) -> List[str]:
        """Returns the non-empty cells in row-major order."""
        names = [name for name, state in self._cells.items() if state['raw'] != '']

        # To sort based on row-major order (Row then Column),
        def sort_key(name: str) -> tuple[int, int]:
            try:
                col_index, row_number = _name_to_coords(name)
                return (row_number, col_index)
            except ValueError:
                # Should not happen for keys in self._cells if they were set correctly
                return (float('inf'), float('inf'))

        return sorted(names, key=sort_key)

    def set(self, name: str, raw: str) -> List[str]:
        """Stores the cell's input and triggers recalculation."""
        if not self._is_valid_name(name):
            raise ValueError(f"Cell name '{name}' is outside the defined sheet boundaries.")
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        # 1. Store the raw input and check for structural changes
        old_raw = self._get_cell_state(name)['raw']
        if old_raw == raw:
            return [] # No change

        new_state = {'raw': raw}
        new_value: Any = None

        # 2. Determine cell value type
        if raw == '':
            new_value = None
        elif raw.startswith('='):
            # Formula cell
            formula_source = raw[1:].strip()
            if not formula_source: # Empty formula '= ' or just '='
                raise FormulaError("Formula input cannot be empty.")

            try:
                # Parse the formula
                tree = parse_formula(formula_source)

                # Get cell references before evaluating to update graph
                # We use the reference resolver which handles internal/external refs
                references_set = references(tree, self)

                # Temporarily update the graph for dependency tracking
                self._graph.set_dependencies(name, references_set)

                # We defer evaluation until recalculation phase
                new_value = 'FORMULA_PENDING'

            except FormulaError as e:
                # Formula parsing failed, sheet state remains unchanged
                raise e
        else:
            # Literal value (Number or Text)
            try:
                # Attempt to parse as a number (int or float)
                stripped_raw = raw.strip()
                if stripped_raw: 
                    if '.' in stripped_raw: 
                        new_value = float(stripped_raw)
                    else:
                        new_value = int(stripped_raw)
                else:
                    new_value = None
            except ValueError:
                # Not a recognized number format, treat as text
                new_value = raw

        # Update cell storage
        self._cells[name] = new_state.copy()
        self._cells[name]['value'] = new_value

        # 3. Recalculation trigger
        if new_value != 'FORMULA_PENDING':
            # If it's literal, the change is immediate for the cell itself.
            affected_cells = [name]
        else:
            # If it's a formula, the change affects itself AND all its dependents.
            affected_cells = list(self._graph.all_dependents(name))

        # Remove duplicates and ensure row-major order for the list of affected cells.
        def sort_key_set(name: str) -> tuple[int, int]:
            try:
                col_index, row_number = _name_to_coords(name)
                return (row_number, col_index)
            except ValueError:
                return (float('inf'), float('inf'))

        unique_affected_cells = sorted(list(set(affected_cells)), key=sort_key_set)

        # 4. Execute Recalculation
        self._recalculate(unique_affected_cells)

        return unique_affected_cells

    def _recalculate(self, cells_to_evaluate: List[str]) -> None:
        """Executes the specialized recalculation sequence."""
        cells_to_evaluate = list(set(cells_to_evaluate)) # Ensure unique

        for name in cells_to_evaluate:
            state = self._get_cell_state(name)
            current_raw = state['raw']

            if not current_raw.startswith('='): 
                continue 

            # Check for cycles
            if name in self._graph.cycle_cells():
                state['value'] = ERROR_CYCLE
                continue

            # Check if evaluation is needed (i.e., not already evaluated/stable)
            # In a ripple effect, we evaluate if we were triggered.
            try:
                # Re-parse to get the tree
                tree = parse_formula(current_raw[1:].strip())

                # Perform evaluation. Pass self.get() which is now aware of sheet boundaries/REF errors.
                evaluated_value = evaluate(tree, self.get)

                # Update state and increment counter
                state['value'] = evaluated_value
                self.evaluations += 1

            except FormulaError as e:
                # Calculation failed (e.g., division by zero, invalid reference, function error, etc.)
                # We need to map specific FormulaErrors to specific ErrorValues as required by the prompt.
                if isinstance(e, DivisionByZeroError):
                    state['value'] = ERROR_DIV_ZERO
                elif isinstance(e, TypeError):
                    state['value'] = ERROR_VALUE
                elif isinstance(e, ReferenceError):
                    # This catches refs that evaluate to outside sheet boundaries, which is now handled by the ref resolver
                    state['value'] = ERROR_REF
                elif isinstance(e, UnknownFunctionError):
                    # Unknown function name
                    state['value'] = ERROR_VALUE
                else:
                    # Catch all others, defaulting to generic error for now, matching original behavior context.
                    state['value'] = ERRORValue('#ERROR!')

                # Ensure cycle error is set if it wasn't caught above (safety net)
                if isinstance(e, CycleError):
                    state['value'] = ERROR_CYCLE

        pass

import re
from typing import Any, List, Set, Union, Dict, Callable, Tuple

class FormulaError(ValueError):
    """Raised when a formula is syntactically incorrect or references invalid cells."""
    pass

class ErrorValue(str):
    """Represents a calculated error value in a cell."""
    pass

# --- AST Node Definitions ---

class FormulaNode:
    pass

class NumberNode(FormulaNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode(FormulaNode):
    """Represents a reference to a single cell (e.g., A1)."""
    def __init__(self, name: str):
        self.name = name

class RangeRefNode(FormulaNode):
    """Represents a reference range (e.g., A1:B2)."""
    def __init__(self, start_ref: str, end_ref: str):
        self.start_ref = start_ref
        self.end_ref = end_ref

class BinaryOpNode(FormulaNode):
    def __init__(self, left: FormulaNode, op: str, right: FormulaNode):
        self.left = left
        self.op = op  # '+', '-', '*', '/'
        self.right = right

class UnaryOpNode(FormulaNode):
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op  # '+', '-' (unary)
        self.operand = operand

class ParenthesizedExprNode(FormulaNode):
    def __init__(self, expr: FormulaNode):
        self.expr = expr

class CallNode(FormulaNode):
    """Represents a function call: fname(arg1, arg2, ...)"""
    def __init__(self, fname: str, args: List[FormulaNode]):
        self.fname = fname
        self.args = args

# --- Tokenization ---

# Regex for tokens: numbers, references, operators, parentheses, function names, range separator
TOKEN_SPECIFICATION = [ 
    # Numbers
    ('NUMBER', r'\b\d+(\.\d+)?\b'), 
    # References (Letters+Digits)
    ('REF', r'[a-zA-Z]+[0-9]+'), 
    # Range Separator
    ('RANGE_SEP', r':'),
    # Function Names (case-insensitive check later)
    ('FUNC', r'SUM|AVG|MIN|MAX'), 
    # Operators and Parentheses
    ('PLUS', r'\+'),
    ('MINUS', r'\-'),
    ('MUL', r'\*'),
    ('DIV', r'/'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('SKIP', r'[ \t]+'), # Whitespace
    ('MISMATCH', r'.')
]

TOKEN_REGEX = '|'.join('(?P<%s>%s)' % pair for pair in TOKEN_SPECIFICATION)

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

def tokenize(source: str) -> List[Token]:
    tokens = []
    # Use re.finditer with the combined regex pattern
    for mo in re.finditer(TOKEN_REGEX, source):
        kind = mo.lastgroup
        value = mo.group()

        if kind == 'NUMBER':
            tokens.append(Token('NUMBER', value))
        elif kind == 'REF':
            tokens.append(Token('REF', value.upper())) # Store references uppercase immediately
        elif kind == 'RANGE_SEP':
            tokens.append(Token('RANGE_SEP', value))
        elif kind == 'FUNC':
            tokens.append(Token('FUNC', value.upper())) # Function names stored uppercase
        elif kind in ('PLUS', 'MINUS', 'MUL', 'DIV', 'LPAREN', 'RPAREN'):
            tokens.append(Token(kind, value))
        elif kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Invalid character in formula: {value}")

    tokens.append(Token('EOF', ''))
    return tokens

# --- Validation Helpers ---

MAX_ROWS = 999
MAX_COLS = 26

def is_valid_reference(ref_name: str) -> bool:
    """Validates if a reference name adheres to sheet constraints (A1-Z999)."""
    if not ref_name or not ref_name[0].isalpha():
        return False

    col_str = ''
    row_str = ''

    i = 0
    while i < len(ref_name) and ref_name[i].isalpha():
        col_str += ref_name[i]
        i += 1
    row_str = ref_name[i:]

    if not col_str or not row_str or not row_str.isdigit():
        return False

    if len(row_str) > 1 and row_str.startswith('0'):
        return False # Leading zero check (e.g., A01)

    try:
        row_num = int(row_str)
        if not (1 <= row_num <= MAX_ROWS):
            return False # Row out of bounds
    except ValueError:
        return False

    col_index_val = 0
    for char in col_str:
        col_index_val = col_index_val * 26 + (ord(char) - ord('A')) + 1

    if col_index_val > MAX_COLS:
        return False # Column out of bounds

    return True

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token: 
        return self.tokens[self.pos]

    def consume(self, expected_type: str = None, expected_value: str = None) -> Token:
        token = self.current_token()
        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, but got {token.type} ({token.value}) at position {self.pos}")
        if expected_value and token.value != expected_value:
            raise FormulaError(f"Expected token value {expected_value}, but got {token.value} at position {self.pos}")
        self.pos += 1
        return token

    def parse(self) -> FormulaNode:
        node = self.expression()
        self.consume('EOF') # Ensure we consumed everything
        return node

    def expression(self) -> FormulaNode:
        """Handles addition and subtraction (lowest precedence)"""
        node = self.term()

        while self.current_token().type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            right = self.term()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def term(self) -> FormulaNode:
        """Handles multiplication and division (medium precedence)"""
        node = self.unary()

        while self.current_token().type in ('MUL', 'DIV'):
            op_token = self.consume()
            right = self.unary()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def unary(self) -> FormulaNode:
        """Handles unary signs, numbers, references, ranges, or parenthesized/function calls (highest precedence)"""
        token = self.current_token()

        if token.type == 'MINUS' or token.type == 'PLUS':
            op_token = self.consume()
            operand = self.unary() # Unary operators bind tightly to the next term
            return UnaryOpNode(op_token.value, operand)

        elif token.type == 'NUMBER':
            self.consume('NUMBER')
            try:
                value_str = token.value
                if '.' in value_str:
                    return NumberNode(float(value_str))
                else:
                    return NumberNode(int(value_str))
            except ValueError:
                raise FormulaError("Internal error: Invalid number format conversion.")

        elif token.type == 'REF':
            ref_token = self.consume('REF')
            # Validation happens at evaluation time for #REF!, but parsing checks format.
            if not is_valid_reference(ref_token.value):
                 raise FormulaError(f"Invalid cell reference format: {ref_token.value}")
            return RefNode(ref_token.value)

        elif token.type == 'RANGE_SEP':
             raise FormulaError("Range separator ':' is not allowed outside of function arguments.")

        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            expr_node = self.expression()
            self.consume('RPAREN')
            return ParenthesizedExprNode(expr_node)

        elif token.type == 'FUNC':
            return self.parse_function_call()

        else:
            raise FormulaError(f"Unexpected token while parsing unary expression: {token.type} ({token.value}) at position {self.pos}")

    def parse_function_call(self) -> CallNode:
        """Parses a function call: FUNC(arg, arg, ...)"""
        fname_token = self.consume('FUNC')
        fname = fname_token.value

        # Expect '(' immediately after function name
        self.consume('LPAREN')

        args: List[FormulaNode] = []

        # Loop to parse arguments, stopping at ')'
        while self.current_token().type != 'RPAREN' and self.current_token().type != 'EOF':
            arg_node = self.argument()
            args.append(arg_node)

            # Check for comma separator (comma is implicitly handled by the recursive structure, but explicit ',' is needed for function args)
            if self.current_token().type == 'PLUS' or self.current_token().type == 'MINUS': # Check for next expression start
                 # If we hit an operator, it implies another argument or end of list, we rely on the argument parser to stop.
                 pass

            # Since we only have +, -, *, / tokens, we assume arguments are separated by an implied separator or parenthesis closure.
            # Based on standard grammar, arguments are separated by commas. Since ',' is not in TOKEN_SPECIFICATION, we must assume arguments are separated by the start of the next valid expression.
            # For now, we rely on the recursion stopping correctly when the next token is 'RPAREN'.
            # A proper grammar would need a COMMA token. Assuming sequential parsing handles separation until ')' or EOF.
            pass 

        self.consume('RPAREN')
        return CallNode(fname, args)

    def argument(self) -> FormulaNode:
        """Parses a single argument: ref : ref | expr"""
        # Peek ahead to see if it's a range reference
        current = self.current_token()

        if current.type == 'REF':
            # Check if the next token is RANGE_SEP
            if self.tokens[self.pos+1].type == 'RANGE_SEP':
                start_ref = self.consume('REF').value
                self.consume('RANGE_SEP')
                end_ref_token = self.consume('REF')
                # Range arguments are always valid references syntactically, but validity is checked in evaluation
                return RangeRefNode(start_ref, end_ref_token.value)
            else:
                # Single reference argument
                return self.unary()
        else:
            # Must be a full expression
            return self.expression()


def parse_formula(source: str) -> FormulaNode:
    """Parses the text after '=' into a syntax tree."""
    source = source.strip()
    if not source: 
        raise FormulaError("Formula source cannot be empty.")

    try:
        tokens = tokenize(source)
        parser = Parser(tokens)
        return parser.parse()
    except FormulaError as e:
        raise e
    except IndexError:
        raise FormulaError("Incomplete or malformed formula expression.")

# --- Evaluation Logic ---

# LookupFunction now needs to be aware of cycle tracking context
LookupFunction = Callable[[str, Set[str]], Tuple[Any, Set[str]]]

def _apply_op(left_val: Any, op: str, right_val: Any) -> Any:
    """Applies binary operation respecting types and error rules (Specific Errors)."""
    # Rule 3: Error propagation (left wins)
    if isinstance(left_val, ErrorValue): return left_val
    if isinstance(right_val, ErrorValue): return right_val

    # Rule 3: Text operand check
    left_is_text = isinstance(left_val, str) and not isinstance(left_val, ErrorValue)
    right_is_text = isinstance(right_val, str) and not isinstance(right_val, ErrorValue)

    if left_is_text or right_is_text: 
        return ErrorValue("#VALUE!") # Specific Value error

    # At this point, both operands should be numbers (int, float) or 0.0 if derived from None.
    try:
        l_num = float(left_val)
        r_num = float(right_val)

        if op == '+':
            result = l_num + r_num
        elif op == '-':
            result = l_num - r_num
        elif op == '*':
            result = l_num * r_num
        elif op == '/':
            if r_num == 0:
                return ErrorValue("#DIV/0!") # Specific Div/0! error
            result = l_num / r_num
        else:
            # Should be unreachable
            return ErrorValue("#VALUE!") 

        # Return as int if it's a whole number and both original inputs were integers
        is_left_int = isinstance(left_val, int)
        is_right_int = isinstance(right_val, int)

        if (op in ('+', '-', '*') and result == int(result) and is_left_int and is_right_int):
             return int(result)

        return result

    except (TypeError, ValueError):
        return ErrorValue("#VALUE!")

def _collect_range_values(range_node: RangeRefNode, lookup: LookupFunction, cycle_stack: Set[str]) -> Tuple[List[Union[int, float, ErrorValue]], ErrorValue | None]:
    """Collects numeric values from a range, returns list of values and immediate error if found."""
    # NOTE: This function assumes lookup can resolve ranges correctly by fetching all cells in the rectangle.
