# This function implements the core range logic.
def _evaluate_range_cells(sheet: MockSheet, range_node: RangeNode) -> Union[List[float], ErrorValue]:
    """
    Evaluates a range node: collects numbers in row-major order, propagates errors, 
    and returns the list of numbers or an ErrorValue.
    """
    start_ref = range_node.start_ref
    end_ref = range_node.end_ref

    try:
        # 1. Get coordinates. This will raise ValueError/IndexError if out of bounds.
        start_col_idx, start_row = _name_to_coords(start_ref)
        end_col_idx, end_row = _name_to_coords(end_ref)
    except ValueError: 
        # If parsing fails due to format/bounds, it's treated as #REF! if it looks like a reference
        return ErrorValue('#REF!')
    except IndexError: 
        # If column index is invalid (should be caught by _name_to_coords but safe check)
        return ErrorValue('#REF!')

    # 2. Normalize iteration boundaries (min/max for row/col)
    min_row = min(start_row, end_row)
    max_row = max(start_row, end_row)
    min_col = min(start_col_idx, end_col_idx)
    max_col = max(start_col_idx, end_col_idx)

    numbers: List[float] = []

    # 3. Iterate row-major (Row increases first, then Column)
    for row in range(min_row, max_row + 1):
        for col_idx in range(min_col, max_col + 1):
            cell_name = _coords_to_name(col_idx, row)

            # 4. Retrieve cell state
            cell_value = sheet.get(cell_name)

            if isinstance(cell_value, ErrorValue):
                # Error propagation: return the leftmost error immediately
                return cell_value

            if cell_value is None: 
                # Empty cell, skip
                continue

            if isinstance(cell_value, str) and cell_value.strip() == '':
                 # Empty text cell, skip
                continue

            # Check if the value is a number (it should be float/int if it's a number)
            if isinstance(cell_value, (int, float)):
                numbers.append(float(cell_value))
            # If it's text, it is skipped as per requirement: "a cell holding a number is collected, an empty cell or a text cell is skipped"

    return numbers

