# --- Custom Errors and Values ---

class FormulaError(ValueError):
    """Raised when a formula is syntactically incorrect or references invalid cells."""
    pass

class ErrorValue(str):
    """Represents a calculated error value in a cell."""
    def __new__(cls, value: str):
        instance = super().__new__(cls)
        instance._value_ = value
        return instance

    def __str__(self): return self._value_ # Required for propagation
    def __repr__(self): return f"ErrorValue('{self._value_}')"

# Predefined Error Values
DIV_BY_ZERO = ErrorValue("#DIV/0!")
VALUE_ERROR = ErrorValue("#VALUE!")
REF_ERROR = ErrorValue("#REF!")
CYCLE_ERROR = ErrorValue("#CYCLE!")

# --- AST Node Definitions ---

class FormulaNode:
    """Base class for AST nodes. Must implement evaluate method."""
    def evaluate(self, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        raise NotImplementedError("Subclasses must implement evaluate")

class NumberNode(FormulaNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

    def evaluate(self, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        return self.value

class RefNode(FormulaNode):
    """Represents a single cell reference (e.g., A1)."""
    def __init__(self, name: str):
        self.name = name

    def evaluate(self, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        # Single reference is treated as a one-cell range evaluation for simplicity
        return context.get_cell_value(self.name)

class RangeNode(FormulaNode):
    """Represents a range defined by two opposite corners (e.g., B3:A1)."""
    def __init__(self, start_ref: str, end_ref: str):
        self.start_ref = start_ref
        self.end_ref = end_ref

    def evaluate(self, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        # This method is primarily used by RangeArgumentEvaluator logic
        return context.evaluate_range(self.start_ref, self.end_ref)

class BinaryOpNode(FormulaNode):
    def __init__(self, left: FormulaNode, op: str, right: FormulaNode):
        self.left = left
        self.op = op  # '+', '-', '*', '/'
        self.right = right

    def evaluate(self, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        left_val = self.left.evaluate(context)
        right_val = self.right.evaluate(context)

        # Error Propagation Check (Leftmost error wins)
        if isinstance(left_val, ErrorValue): return left_val
        if isinstance(right_val, ErrorValue): return right_val

        l_num = left_val if isinstance(left_val, (int, float)) else None
        r_num = right_val if isinstance(right_val, (int, float)) else None

        # Value Error Check (Operand must be numeric)
        if l_num is None or r_num is None:
            return VALUE_ERROR

        try:
            if self.op == '+': return l_num + r_num
            if self.op == '-': return l_num - r_num
            if self.op == '*': return l_num * r_num
            if self.op == '/':
                if r_num == 0: return DIV_BY_ZERO
                return l_num / r_num
        except Exception:
            # Should be caught by numeric check, but as a safeguard
            return VALUE_ERROR

        return VALUE_ERROR # Should be unreachable

class UnaryOpNode(FormulaNode):
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op  # '+', '-' (unary)
        self.operand = operand

    def evaluate(self, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        operand_val = self.operand.evaluate(context)

        if isinstance(operand_val, ErrorValue): return operand_val

        operand_num = operand_val if isinstance(operand_val, (int, float)) else None

        if operand_num is None:
            return VALUE_ERROR

        if self.op == '+': return operand_num
        if self.op == '-': return -operand_num

        return VALUE_ERROR # Should be unreachable

class ParenthesizedExprNode(FormulaNode):
    def __init__(self, expr: FormulaNode):
        self.expr = expr

    def evaluate(self, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        return self.expr.evaluate(context)

class FunctionCallNode(FormulaNode):
    """Represents a function call, e.g., =SUM(A1:A3, B5)."""
    def __init__(self, fname: str, args: List[FormulaNode]):
        self.fname = fname.upper()
        self.args = args

    def evaluate(self, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        # 1. Collect numbers from arguments, checking for errors at each step
        collected_values: List[Union[float, int]] = []
        first_error: Optional[ErrorValue] = None

        for arg_node in self.args:
            arg_result = self._evaluate_argument_for_collection(arg_node, context)

            # 2. Error Check: If an error occurred in the argument evaluation, it is the call's result.
            if isinstance(arg_result, ErrorValue):
                # The first error encountered during argument evaluation dictates the final result
                return arg_result

            # 3. Collection: If successful, collect the number
            collected_values.append(arg_result)

        # 4. Computation (if no errors found)
        if not collected_values:
            if self.fname == 'SUM': return 0
            if self.fname == 'AVG': return DIV_BY_ZERO
            if self.fname in ('MIN', 'MAX'): return 0

        if self.fname == 'SUM':
            return sum(collected_values)

        if self.fname == 'AVG':
            return sum(collected_values) / len(collected_values)

        if self.fname == 'MIN':
            return min(collected_values)

        if self.fname == 'MAX':
            return max(collected_values)

        return VALUE_ERROR # Should not happen for known functions

    def _evaluate_argument_for_collection(self, arg_node: FormulaNode, context: 'EvaluationContext') -> Union[float, int, ErrorValue]:
        """Evaluates an argument based on the rules: Range -> specific logic; Ref/Expr -> general logic."""

        # Case 1: The argument is a RangeNode (e.g., A1:B3)
        if isinstance(arg_node, RangeNode):
            return context.evaluate_range(arg_node.start_ref, arg_node.end_ref)

        # Case 2: The argument is a RefNode or a general expression (FormulaNode)
        if isinstance(arg_node, RefNode) or isinstance(arg_node, BinaryOpNode) or isinstance(arg_node, UnaryOpNode) or isinstance(arg_node, ParenthesizedExprNode):

            # Rule: An argument that is a single reference, with or without parentheses, is treated as a one-cell range, so text in it is skipped.
            if isinstance(arg_node, RefNode):
                # Treat as one-cell range evaluation
                return context.get_cell_value(arg_node.name)

            # Rule: Any other argument is evaluated as an expression.
            expr_result = arg_node.evaluate(context)

            # Expression Result Check
            if isinstance(expr_result, ErrorValue):
                # Error value becomes the call's result
                return expr_result

            # Number Collection: If it's a number, collect it.
            if isinstance(expr_result, (int, float)):
                return expr_result

            # Text/Other: Text gives #VALUE!
            return VALUE_ERROR

        # Should not be reachable
        return VALUE_ERROR

# --- Tokenization ---

FUNCTION_NAMES = {'SUM', 'AVG', 'MIN', 'MAX'}

TOKEN_SPECIFICATION = [ 
    # Numbers
    ('NUMBER', r'\b\d+(\.\d+)?\b'), 
    # References (Letters+Digits)
    ('REF', r'[a-zA-Z]+[0-9]+'), 
    # Range delimiter
    ('RANGE_SEP', r':'),
    # Function/Keyword Names
    ('FUNCTION', r'(SUM|AVG|MIN|MAX)'), 
    # Operators and Parentheses
    ('PLUS', r'\+'),
    ('MINUS', r'\-'),
    ('MUL', r'\*'),
    ('DIV', r'/'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    # Separator (Crucial for function arguments)
    ('COMMA', r','),
    ('SKIP', r'[ \t]+'), # Whitespace
    ('MISMATCH', r'.')
]

TOKEN_REGEX = '|'.join('(?P<%s>%s)' % pair for pair in TOKEN_SPECIFICATION)

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

def tokenize(source: str) -> List[Token]:
    tokens = []
    # Use re.finditer with the combined regex pattern
    for mo in re.finditer(TOKEN_REGEX, source):
        kind = mo.lastgroup
        value = mo.group()

        if kind == 'NUMBER':
            tokens.append(Token('NUMBER', value))
        elif kind == 'REF':
            tokens.append(Token('REF', value.upper()))
        elif kind == 'FUNCTION':
            tokens.append(Token('FUNCTION', value.upper()))
        elif kind == 'RANGE_SEP':
            tokens.append(Token('RANGE_SEP', value))
        elif kind == 'COMMA':
            tokens.append(Token('COMMA', value))
        elif kind in ('PLUS', 'MINUS', 'MUL', 'DIV', 'LPAREN', 'RPAREN'):
            tokens.append(Token(kind, value))
        elif kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Invalid character in formula: {value}")

    tokens.append(Token('EOF', ''))
    return tokens

# --- Validation Helpers ---

MAX_ROWS = 999
MAX_COLS = 26

def is_valid_reference(ref_name: str) -> bool:
    """Validates if a reference name adheres to sheet constraints."""
    if not ref_name or not ref_name[0].isalpha():
        return False

    col_str = ''
    row_str = ''

    i = 0
    while i < len(ref_name) and ref_name[i].isalpha():
        col_str += ref_name[i]
        i += 1
    row_str = ref_name[i:]

    if not col_str or not row_str or not row_str.isdigit():
        return False 

    # Check for leading zeros in row number
    if len(row_str) > 1 and row_str.startswith('0'):
        return False 

    try:
        row_num = int(row_str)
        if not (1 <= row_num <= MAX_ROWS):
            return False 
    except ValueError:
        return False

    # Column validation
    col_index_val = 0
    for char in col_str:
        col_index_val = col_index_val * 26 + (ord(char) - ord('A')) + 1

    if col_index_val > MAX_COLS:
        return False 

    return True

