from typing import List, Tuple

class TicTacToe:
    """Tic-Tac-Toe game state."""
    def __init__(self, board: str = '.........'):
        if len(board) != 9:
            raise ValueError("Board must have a length of 9.")

        counts = {'X': 0, 'O': 0}
        for char in board:
            if char not in ('X', 'O', '.'):
                raise ValueError("Board characters must be 'X', 'O', or '.'")
            if char == 'X':
                counts['X'] += 1
            elif char == 'O':
                counts['O'] += 1

        if counts['X'] > counts['O'] + 1 or counts['O'] > counts['X']:
            raise ValueError("Impossible counts of X and O on the board.")

        self.board = board

    def _get_player(self) -> str:
        """Determines whose turn it is."""
        counts = {'X': 0, 'O': 0}
        for char in self.board:
            if char == 'X':
                counts['X'] += 1
            elif char == 'O':
                counts['O'] += 1

        if counts['X'] == counts['O']:
            return 'X'
        elif counts['X'] == counts['O'] + 1:
            return 'O'
        else:
            # Should be caught by constructor validation, but defensive check
            raise RuntimeError("Internal state error: player cannot be determined.")

    def moves(self) -> List[int]:
        """Returns the legal moves (available square numbers) in ascending order."""
        return [i for i, char in enumerate(self.board) if char == '.']

    def play(self, move: int) -> 'TicTacToe':
        """Returns a new state with the move made."""
        if move < 0 or move > 8 or self.board[move] != '.':
            raise ValueError("Illegal move: Square is taken or out of bounds.")

        new_board_list = list(self.board)
        new_board_list[move] = self.player
        return TicTacToe("".join(new_board_list))

    def winner(self) -> str | None:
        """Returns the winner ('X' or 'O') or None if no winner."""
        board = self.board
        # Check rows
        for i in range(3):
            if all(board[i*3 + j] == self.player for j in range(3)): return self.player
        # Check columns
        for j in range(3):
            if all(board[i*3 + j] == self.player for i in range(3)): return self.player
        # Check diagonals
        if all(board[i*3 + i] == self.player for i in range(3)): return self.player
        if all(board[i*3 + (2-i)] == self.player for i in range(3)): return self.player
        return None

    def is_over(self) -> bool:
        """True when there is a winner or the board is full."""
        return self.winner() is not None or not self.moves() is None

    def str(self) -> str:
        """Returns the board string, one line per row (no trailing newline)."""
        return self.board[0:3] + '\n' + self.board[3:6] + '\n' + self.board[6:9]

    def __repr__(self):
        return f"TicTacToe(board='{self.board}')"

    def __eq__(self, other):
        if isinstance(other, TicTacToe):
            return self.board == other.board
        return NotImplemented

    def __hash__(self):
        return hash(self.board)

    @classmethod
    def from_moves(cls, moves: List[int]):
        """Plays a sequence of moves starting from an empty board."""
        current_state = cls()
        for i, move in enumerate(moves):
            try:
                current_state = current_state.play(move)
            except ValueError as e:
                raise ValueError(f"Illegal move at step {i}: {e}")
        return current_state

