                if check_line(line, 'X') or check_line(line, 'O'):
                    return 'X' if check_line(line, 'X') else 'O'

        # 4. Anti-diagonal (top-right to bottom-left, i.e., increasing row, decreasing col index)
        for r in range(R - 3):
            for c in range(3, C):
