from typing import List, Tuple

class TicTacToe:
    """Tic-Tac-Toe game state."""
    def __init__(self, board: str = '.........'):
        if len(board) != 9:
            raise ValueError("Board must have a length of 9.")

        counts = {'X': 0, 'O': 0}
        for char in board:
            if char not in ('X', 'O', '.'):
                raise ValueError("Board characters must be 'X', 'O', or '.'")
            if char == 'X':
                counts['X'] += 1
            elif char == 'O':
                counts['O'] += 1

        if counts['X'] > counts['O'] + 1 or counts['O'] > counts['X']:
            raise ValueError("Impossible counts of X and O on the board.")

        self.board = board

    def _get_player(self) -> str:
        """Determines whose turn it is."""
        counts = {'X': 0, 'O': 0}
        for char in self.board:
            if char == 'X':
                counts['X'] += 1
            elif char == 'O':
                counts['O'] += 1

        if counts['X'] == counts['O']:
            return 'X'
        elif counts['X'] == counts['O'] + 1:
            return 'O'
        else:
            # Should be caught by constructor validation, but defensive check
            raise RuntimeError("Internal state error: player cannot be determined.")

    def moves(self) -> List[int]:
        """Returns the legal moves (available square numbers) in ascending order."""
        return [i for i, char in enumerate(self.board) if char == '.']

    def play(self, move: int) -> 'TicTacToe':
        """Returns a new state with the move made."""
        if move < 0 or move > 8 or self.board[move] != '.':
            raise ValueError("Illegal move: Square is taken or out of bounds.")

        new_board_list = list(self.board)
        new_board_list[move] = self.player
        return TicTacToe("".join(new_board_list))

    def winner(self) -> str | None:
        """Returns the winner ('X' or 'O') or None if no winner."""
        board = self.board
        # Check rows
        for i in range(3):
            if all(board[i*3 + j] == self.player for j in range(3)): return self.player
        # Check columns
        for j in range(3):
            if all(board[i*3 + j] == self.player for i in range(3)): return self.player
        # Check diagonals
        if all(board[i*3 + i] == self.player for i in range(3)): return self.player
        if all(board[i*3 + (2-i)] == self.player for i in range(3)): return self.player
        return None

    def is_over(self) -> bool:
        """True when there is a winner or the board is full."""
        return self.winner() is not None or not self.moves() is None

    def str(self) -> str:
        """Returns the board string, one line per row (no trailing newline)."""
        return self.board[0:3] + '\n' + self.board[3:6] + '\n' + self.board[6:9]

    def __repr__(self):
        return f"TicTacToe(board='{self.board}')"

    def __eq__(self, other):
        if isinstance(other, TicTacToe):
            return self.board == other.board
        return NotImplemented

    def __hash__(self):
        return hash(self.board)

    @classmethod
    def from_moves(cls, moves: List[int]):
        """Plays a sequence of moves starting from an empty board."""
        current_state = cls()
        for i, move in enumerate(moves):
            try:
                current_state = current_state.play(move)
            except ValueError as e:
                raise ValueError(f"Illegal move at step {i}: {e}")
        return current_state

from typing import List, Tuple, Optional

class ConnectFour:
    """Connect-Four game state."""
    def __init__(self, columns: int = 7, rows: int = 6):
        if columns < 1 or rows < 1:
            raise ValueError("Columns and rows must be at least 1.")
        self.columns = columns
        self.rows = rows
        # Internal representation: board[row][column], row 0 is bottom.
        # Initialize board with '.'
        self.board = [['.' for _ in range(columns)] for _ in range(rows)]

    def __eq__(self, other):
        if isinstance(other, ConnectFour):
            return self.columns == other.columns and self.rows == other.rows and self.board == other.board
        return NotImplemented

    def __hash__(self):
        # Hashing nested lists is complex/discouraged, but for immutability context, we rely on board equality check elsewhere if needed.
        # For simplicity in this context, we rely on state comparison via ==.
        return hash((tuple(tuple(row) for row in self.board), self.columns, self.rows))

    def player(self) -> str:
        # Determine player based on piece counts
        count_x = sum(row.count('X') for row in self.board)
        count_o = sum(row.count('O') for row in self.board)
        if count_x == count_o: # X always moves first
            return 'X'
        elif count_x == count_o + 1:
            return 'O'
        else:
            # This state should ideally not happen if moves are played correctly
            raise ValueError("Invalid game state: player count imbalance.")

    def moves(self) -> List[int]:
        """Returns the legal moves (column numbers) in ascending order."""
        legal_moves = []
        for col in range(self.columns):
            # Check if the top row (rows - 1) of this column is empty
            if self.board[self.rows - 1][col] == '.':
                legal_moves.append(col)
        return legal_moves

    def _get_piece_at(self, col: int, row: int) -> str:
        if 0 <= row < self.rows and 0 <= col < self.columns:
            return self.board[row][col]
        raise IndexError("Coordinates outside board boundaries.")

    def play(self, move: int) -> 'ConnectFour':
        """Returns a new state with the move made. Move is a column index."""
        if move not in self.moves():
            raise ValueError("Illegal move: Column is full or outside board limits.")

        new_board = [row[:] for row in self.board] # Deep copy

        # Find the lowest empty row in the chosen column
        for r in range(self.rows):
            if new_board[r][move] == '.':
                # The piece falls to this row
                new_board[r][move] = self.player()
                break

        # Create a new immutable state instance
        new_state = ConnectFour(self.columns, self.rows)
        new_state.board = new_board
        return new_state

    def winner(self) -> Optional[str]:
        # Check for four in a row (horizontal, vertical, diagonal)
        C = self.columns
        R = self.rows

        def check_line(cells: List[str], player_id: str) -> bool:
            return all(cell == player_id for cell in cells)

        # 1. Horizontal check
        for r in range(R):
            for c in range(C - 3):
                line = [self.board[r][c+i] for i in range(4)]
                if check_line(line, 'X') or check_line(line, 'O'):
                    return 'X' if check_line(line, 'X') else 'O'

        # 2. Vertical check
        for c in range(C):
            for r in range(R - 3):
                line = [self.board[r+i][c] for i in range(4)]
                if check_line(line, 'X') or check_line(line, 'O'):
                    return 'X' if check_line(line, 'X') else 'O'

        # 3. Diagonal (top-left to bottom-right, i.e., increasing row/col index)
        for r in range(R - 3):
            for c in range(C - 3):
                line = [self.board[r+i][c+i] for i in range(4)]
                if check_line(line, 'X') or check_line(line, 'O'):
                    return 'X' if check_line(line, 'X') else 'O'

        # 4. Anti-diagonal (top-right to bottom-left, i.e., increasing row, decreasing col index)
        for r in range(R - 3):
            for c in range(3, C):
                line = [self.board[r+i][c-i] for i in range(4)]
                if check_line(line, 'X') or check_line(line, 'O'):
                    return 'X' if check_line(line, 'X') else 'O'

        return None

    def is_over(self) -> bool:
        return self.winner() is not None or not self.moves() # Board full if no moves are legal

    def str(self) -> str:
        # Shows the top row first.
        # Board is stored row 0 = bottom, row R-1 = top.
        output_lines = []
        for r in range(self.rows - 1, -1, -1):
            output_lines.append("".join(self.board[r]))
        return "\n".join(output_lines) # No trailing newline

    @classmethod
    def from_moves(cls, moves: List[int], columns: int = 7, rows: int = 6) -> 'ConnectFour':
        """Plays a sequence of moves starting from an empty board."""
        current_state = cls(columns, rows)
        for i, move in enumerate(moves):
            try:
                current_state = current_state.play(move)
            except ValueError as e:
                raise ValueError(f"Illegal move at step {i}: {e}")
        return current_state

# Heuristic evaluation function (defined separately as required by the prompt structure)
def evaluate(state: ConnectFour) -> int:
    """Heuristic evaluation for depth-limited search in ConnectFour."""
    C = state.columns
    R = state.rows
    total_score = 0

    def get_piece(col: int, row: int) -> str:
        try:
            return state.board[row][col]
        except IndexError:
            return '.'

    def count_pieces(cells: List[str]) -> Tuple[int, int]:
        n_x = sum(1 for cell in cells if cell == 'X')
        n_o = sum(1 for cell in cells if cell == 'O')
        return n_x, n_o

    # Check all windows (lines of 4)

    # 1. Horizontal
    for r in range(R):
