            cells = [get_piece(c+i, r) for i in range(4)]
            n_x, n_o = count_pieces(cells)
            if n_x == 4 or n_o == 4: continue # Win/Loss handled by game logic, score 0 here
            if n_x > 0 and n_o == 0: total_score += (n_x * n_x)
            elif n_o > 0 and n_x == 0: total_score -= (n_o * n_o)
            elif n_x > 0 and n_o > 0: continue # Mixed or empty

    # 2. Vertical
    for c in range(C):
