            n_x, n_o = count_pieces(cells)
            if n_x == 4 or n_o == 4: continue
            if n_x > 0 and n_o == 0: total_score += (n_x * n_x)
            elif n_o > 0 and n_x == 0: total_score -= (n_o * n_o)
