class Empty:
    """Matches the empty string."""
    pass

@dataclass(frozen=True)
class Literal:
    """Matches a specific character."""
    char: str

@dataclass(frozen=True)
class AnyChar:
    """Matches any single character except '\n'."""
    pass

@dataclass(frozen=True)
class CharClass:
    """Character class: list of (low, high) tuples, negated flag."""
    items: Tuple[Tuple[str, str], ...]
    negated: bool

@dataclass(frozen=True)
class Concat:
    """Sequence of nodes."""
    items: Tuple['ASTNode', ...]

@dataclass(frozen=True)
class Alt:
    """Alternative: left to right alternation."""
    options: Tuple['ASTNode', ...]

@dataclass(frozen=True)
class Star:
    """Zero or more repetitions of the node."""
    node: 'ASTNode'

@dataclass(frozen=True)
class Plus:
    """One or more repetitions of the node."""
    node: 'ASTNode'

@dataclass(frozen=True)
class Optional:
    """Zero or one repetition of the node."""
    node: 'ASTNode'

@dataclass(frozen=True)
class Group:
    """Parenthesised sub-pattern."""
    node: 'ASTNode'

# Define a type alias for convenience
ASTNode = Union[Empty, Literal, AnyChar, CharClass, Concat, Alt, Star, Plus, Optional, Group]

# --- Tokenization --- 

class Token:
    def __init__(self, type: str, value: str, position: int): # value might be the character for literals/dots
        self.type = type
        self.value = value
        self.position = position

# Token Types
TT_LITERAL = 'LITERAL'
TT_DOT = 'DOT'
TT_ESCAPE = 'ESCAPE'
TT_CHAR_CLASS_START = 'CHAR_CLASS_START'
TT_CHAR_CLASS_END = 'CHAR_CLASS_END'
TT_OPEN_GROUP = 'OPEN_GROUP'
TT_CLOSE_GROUP = 'CLOSE_GROUP'
TT_ALTERNATION = 'ALTERNATION'
TT_STAR = 'STAR'
TT_PLUS = 'PLUS'
TT_QUESTION = 'QUESTION'

def tokenize(pattern: str) -> Tuple[List[Token], int]:
    """Lexer: Converts pattern string into a list of tokens."""
    tokens: List[Token] = []
    i = 0
    n = len(pattern)

    while i < n:
        char = pattern[i]
        pos = i

        if char == '\':
            if i + 1 >= n:
                raise RegexError("\\ at the end of the pattern", pos)
            next_char = pattern[i+1]
            # Handle escaped characters: \, 
, 	, etc., or literal escapes like 
, 

            # We treat all escaped chars as a literal for the AST, except for \ which escapes itself.
            # The AST expects Literal(char). For escaped chars, the value is the char itself.
            # E.g., \ -> Literal('\'), 
 -> Literal('\n') if we strictly follow the rule, but the rule says "\ followed by any character is that character as a literal".
            # If it's \, it's Literal('\'). If it's 
, it's Literal('n'). This is ambiguous for control chars, so we take the character following the backslash as the literal content.
            tokens.append(Token(TT_ESCAPE, next_char, pos))
            i += 2
            continue

        elif char == '.':
            tokens.append(Token(TT_DOT, '.', pos))
            i += 1
            continue

        elif char == '[':
            # Start of Character Class
            i += 1
            start_pos = pos + 1
            j = i
            items: List[Tuple[str, str]] = []
            is_negated = False

            if pattern[j] == '^':
                is_negated = True
                j += 1

            class_content_start = j

            while j < n and pattern[j] != ']':
                # Escaped characters inside class
                if pattern[j] == '\' and j + 1 < n:
                    j += 1
                    item_char = pattern[j]

                    if item_char == '-' and j + 1 < n and pattern[j+1].isalpha() and pattern[j+1].islower():
                        # This case seems to be for ranges, but the spec says '\ escapes the next character, and every other character... is literal.'
                        # So '\-' should result in Literal('-')
                        items.append((item_char, item_char))
                        j += 1
                        continue
                    else:
                        items.append((item_char, item_char))
                        j += 1
                        continue

                elif pattern[j] == ']': # Should be caught by outer loop, but safety check
                    break

                elif pattern[j] == '-' and items:
                    # Check if it's a valid range start
                    low_char = items[-1][1]
                    if pattern[j+1:j+2].isalpha() and pattern[j+1:j+2].islower():
                        high_char = pattern[j+1]
                        if low_char <= high_char:
                            items.append((low_char, high_char))
                            j += 2
                            continue
                        else:
                            # Error: range whose low end is greater than its high end
                            raise RegexError("Range low end greater than high end", pos + 1)
                    # If it's not a range, treat '-' as literal (e.g., if it's the first item after ^, or last item, or not followed by a letter)
                    items.append((pattern[j], pattern[j]))
                    j += 1
                    continue

                elif pattern[j].isalnum() or pattern[j] in '.|()^*+?[]\': # Basic characters
                    items.append((pattern[j], pattern[j]))
                    j += 1
                    continue

                elif pattern[j] in '()|*+?': # Special chars treated as literal inside class
                    items.append((pattern[j], pattern[j]))
                    j += 1
                    continue

                else: # Any other character (including whitespace)
                    items.append((pattern[j], pattern[j]))
                    j += 1
                    continue

            if j == n and pattern[n-1] != ']':
                 raise RegexError("Unclosed character class [", pos)

            if not items:
                # Error: an empty class [] / [^]
                raise RegexError("Empty character class", pos)

            if j < n and pattern[j] == ']':
                tokens.append(Token(TT_CHAR_CLASS_START, items, pos))
                i = j + 1
                continue

            # Should be unreachable if logic is sound, but defensively break if loop finished unexpectedly
            raise RegexError("Parsing error within character class", pos)

        elif char == ']':
            # This should only be consumed as part of a character class.
            raise RegexError("Unmatched closing character class ], encountered outside [...]", pos)

        elif char in '()[]*+?|
':
            # Grouping, Alternation, Quantifiers
            if char == '(': 
                tokens.append(Token(TT_OPEN_GROUP, '(', pos))
                i += 1
                continue
            if char == ')':
                tokens.append(Token(TT_CLOSE_GROUP, ')', pos))
                i += 1
                continue
            if char == '|':
                tokens.append(Token(TT_ALTERNATION, '|', pos))
                i += 1
                continue
            if char == '*':
                tokens.append(Token(TT_STAR, '*', pos))
                i += 1
                continue
            if char == '+':
                tokens.append(Token(TT_PLUS, '+', pos))
                i += 1
                continue
            if char == '?':
                tokens.append(Token(TT_QUESTION, '?', pos))
                i += 1
                continue

        else: # Literal character (including whitespace)
            tokens.append(Token(TT_LITERAL, char, pos))
            i += 1

    return tokens, n

# --- Parsing Logic (Recursive Descent) ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Token]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_type: str = None, expected_value: str = None) -> Token:
        if self.pos >= len(self.tokens):
            raise RegexError("Unexpected end of pattern", len(self.tokens))

        token = self.tokens[self.pos]

        if expected_type and token.type != expected_type:
            raise RegexError(f"Expected token type {expected_type}, got {token.type}", token.position)
        if expected_value and token.value != expected_value:
            raise RegexError(f"Expected token value {expected_value}, got {token.value}", token.position)

        self.pos += 1
        return token

    # --- Grammar Rules ---

    # Primary -> Literal | AnyChar | CharClass | Group
    def parse_primary(self) -> ASTNode:
        token = self.peek()
        if not token:
            raise RegexError("Unexpected end of pattern when expecting primary expression", self.pos)

        if token.type == TT_LITERAL:
            self.consume(TT_LITERAL)
            return Literal(token.value)

        elif token.type == TT_DOT:
            self.consume(TT_DOT)
            return AnyChar()

        elif token.type == TT_CHAR_CLASS_START:
            self.consume(TT_CHAR_CLASS_START)
            items = token.value
            return CharClass(items, token.value[0] == '^')

        elif token.type == TT_OPEN_GROUP:
            self.consume(TT_OPEN_GROUP)
            node = self.parse_expression()
            self.consume(TT_CLOSE_GROUP)
            return Group(node)

        else:
            # This catches quantifiers at the start, or other unexpected tokens
            raise RegexError(f"Unexpected token at start of primary: {token.type}", token.position)

    # Atom -> Primary (Quantifier)?
    def parse_atom(self) -> ASTNode:
        node = self.parse_primary()
        token = self.peek()

        if token and token.type in [TT_STAR, TT_PLUS, TT_QUESTION]:
            op_token = self.consume()
            if op_token.type == TT_STAR:
                return Star(node)
            elif op_token.type == TT_PLUS:
                return Plus(node)
            elif op_token.type == TT_QUESTION:
                return Optional(node)

        return node

    # Term -> Atom (Concat) -> ...
    # Concatenation binds tighter than '|'.
    def parse_term(self) -> ASTNode:
        # Start with the first atom
        result_list = [self.parse_atom()]

        # Check for implicit concatenation: if the next token is a Primary/Atom starting token
        while self.peek() and self.peek().type not in [TT_ALTERNATION, TT_CLOSE_GROUP]:
            next_token = self.peek()
            if next_token.type in [TT_LITERAL, TT_DOT, TT_CHAR_CLASS_START, TT_OPEN_GROUP]:
                # Implicit concatenation detected
                result_list.append(self.parse_atom())
            else:
                # Stop if it's not a concatenatable element (e.g., if we hit a ')' or '|')
                break

        if len(result_list) == 1:
            return result_list[0]
        return Concat(tuple(result_list))

    # Expression -> Term (Alt) -> ...
    def parse_expression(self) -> ASTNode:
        # Start with the first term
        result_list = [self.parse_term()]

        # Check for explicit alternation '|'
        while self.peek() and self.peek().type == TT_ALTERNATION:
            self.consume(TT_ALTERNATION)
            result_list.append(self.parse_term())

        if len(result_list) == 1:
            return result_list[0]
        return Alt(tuple(result_list))

    def parse(self) -> ASTNode:
        ast = self.parse_expression()
        # Check if there's any leftover input after the top-level expression
        if self.pos < len(self.tokens):
            leftover_token = self.tokens[self.pos]
            # If we have leftover, it must be an error unless it's a closing parenthesis which should have been handled by a Group
            if leftover_token.type not in [TT_CLOSE_GROUP]:
                raise RegexError(f"Unexpected token '{leftover_token.value}' after expression completion", leftover_token.position)

        return ast

# --- Public Interface ---

def parse(pattern: str) -> ASTNode:
    """Parses a regex pattern string into an AST node."""
    if not pattern: 
        return Empty()

    try:
        tokens, _ = tokenize(pattern)
    except RegexError as e:
        # Re-raise errors found during tokenization
        raise e
    except Exception as e:
        # Catch any other unexpected tokenization errors and wrap them
        raise RegexError(f"Tokenization failed: {e}", 0)

    try:
        parser = Parser(tokens)
        return parser.parse()
    except RegexError as e:
        # Re-raise errors found during parsing
        raise e
    except Exception as e:
        # Catch any other unexpected parsing errors and wrap them
        raise RegexError(f"Parsing failed: {e}", 0)

