            for transition in current_state.transitions:
                if transition.symbol is EPSILON and transition.target not in closure:
                    closure.add(transition.target)
                    stack.append(transition.target)
        return closure

    def _transition(self, states: Set[State], char: str) -> Set[State]:
        """Computes the set of states reachable from 'states' by reading 'char'."""
        next_states = set()
        for state in states:
            for transition in state.transitions:
