        """Adds a release of a package to the index."""
        if name in self._packages and version in self._packages[name]:
            raise ValueError(f"Package {name} version {version} already exists in index.")

        if requires is None:
            requires = {}

        validated_requires: Dict[str, Range] = {}
        for dep_name, spec in requires.items():
            # Assuming Range can parse the spec string provided
            try:
                validated_requires[dep_name] = Range(spec)
            except ValueError as e:
                raise ValueError(f"Invalid dependency spec for {name}@{version} on {dep_name}: {e}")

        if name not in self._packages:
            self._packages[name] = {}

        self._packages[name][version] = validated_requires

    def versions(self, name: str) -> List[Version]:
        """Returns the list of known Version objects for a given package name, newest first."""
        if name not in self._packages:
            return []

        # Sort versions: Version objects are hashable and comparable
        return sorted(self._packages[name].keys(), reverse=True)

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns a dict mapping each dependency name to its Range object for a specific Version."""
        if name not in self._packages or version not in self._packages[name]:
            raise KeyError(f"Version {version} of package {name} not found in index.")

        return self._packages[name][version]

