    def from_dict(cls, data: Dict[str, Any]) -> 'PackageIndex':
        """Builds an index from a structured dictionary dataset."""
        index = cls()

        for name, versions_data in data.items():
            if not isinstance(versions_data, dict):
                raise TypeError(f"Data for package {name} must be a dictionary of versions.")

            for version_str, requires_data in versions_data.items():
                try:
                    version = Version(version_str)

                    if not isinstance(requires_data, dict):
                         raise TypeError(f"Requires data for {name}@{version_str} must be a dictionary of dependencies.")

                    validated_requires: Dict[str, Range] = {}
                    for dep_name, spec in requires_data.items():
