                    if not isinstance(requires_data, dict):
                         raise TypeError(f"Requires data for {name}@{version_str} must be a dictionary of dependencies.")

                    validated_requires: Dict[str, Range] = {}
                    for dep_name, spec in requires_data.items():
                        # Assuming Range can parse the spec string provided
                        try:
                            validated_requires[dep_name] = Range(spec)
                        except ValueError as e:
                            # Re-raise validation errors found during load
                            raise ValueError(f"Failed to load {name}@{version_str} from data: {e}")

                    index.add(name, version, requires=validated_requires)

                except ValueError as e:
                    # Catches errors from Version(version_str)
                    raise ValueError(f"Failed to load {name}@{version_str} from data: {e}")

        return index

