from typing import Tuple, List
import posixpath

# Helper functions

def _is_absolute(path: str) -> bool:
    """Checks if a path is absolute (starts with '/')."""
    return path.startswith('/')

def normalize(path: str, cwd: str = '/') -> str:
    """Returns an absolute path with no '.' or '..' parts, no repeated '/', and no trailing '/' (except '/')."""
    if not path:
        raise ValueError("Path cannot be empty.")

    # 1. Determine the starting point
    if _is_absolute(path):
        root = '/'
        path_parts = path.strip('/').split('/')
        cwd_parts = []
    else:
        # Path is relative, resolve against cwd
        if not _is_absolute(cwd): # Should not happen if cwd is enforced as absolute root
             raise ValueError("CWD must be an absolute path.")
        cwd_parts = cwd.strip('/').split('/')
        path_parts = path.split('/')
        root = '' # Handled by joining

    # 2. Process path segments
    resolved_parts = []
    for part in path_parts:
        if part == '.' or part == '':
            continue
        elif part == '..':
            if resolved_parts and resolved_parts[-1] != '..':
                # Go up one level, unless we are at the logical root
                resolved_parts.pop()
            elif not _is_absolute(path) and not resolved_parts: 
                 # If relative and already at root level, '..' is ignored for simplicity in this context, 
                 # though standard POSIX behavior might allow it if not constrained.
                 # Given the rules, '..' at the root stays at the root.
                 pass
            elif _is_absolute(path) and not resolved_parts: 
                 # At root of absolute path, '..' does nothing
                 pass
        else:
            resolved_parts.append(part)

    # 3. Construct the final path
    if _is_absolute(path):
        final_path = posixpath.join(root, *resolved_parts)
    else:
        # Relative path resolved against cwd
        final_path = posixpath.join(cwd, *resolved_parts)

    # Ensure it's normalized according to rules:
    # - no repeated / (posixpath.join handles this)
    # - no . or .. parts (handled by logic)
    # - no trailing / (unless it's the root '/')
    if len(final_path) > 1 and final_path.endswith('/'):
        final_path = final_path.rstrip('/')

    # Final check for root path normalization
    if final_path == '':
        return '/' # Should only happen if path resolves to root

    return final_path


def join(base: str, *parts: str) -> str:
    """Joins paths like posixpath.join (a part starting with '/' starts over) and returns the result normalised."""
    # POSIX join behavior: if a part starts with '/', it overrides the base.
    combined_parts = [base] + list(parts)

    final_parts = []
    for part in combined_parts:
        if part.startswith('/'):
            final_parts = [part] # New absolute path starts here
        elif part: # Ignore empty parts resulting from extra slashes
            final_parts.append(part)

    # Use posixpath.join for joining, then normalize the result
    if not final_parts: 
        return '/' # Should not happen if base is valid

    joined = posixpath.join(*final_parts)
    return normalize(joined, cwd='/')

def split(path: str) -> Tuple[str, str]:
    """Takes an absolute normalised path and returns (parent, name); split('/') is ('/', '')."""
    if path == '/':
        return ('/', '')

    # Path is guaranteed to be absolute and normalized (no trailing slash unless root)
    parent = posixpath.dirname(path)
    name = posixpath.basename(path)
    return (parent, name)

def is_within(path: str, ancestor: str) -> bool:
    """Tells whether the normalised path is ancestor itself or lies below it (/ab is not within /a)."""
    # Ensure both paths are normalized before comparison
    path = normalize(path)
    ancestor = normalize(ancestor)

    if path == ancestor:
        return True

    # Check if path starts with ancestor followed by a separator
    # Example: path=/a/b, ancestor=/a. Path must start with /a/.
    # Since paths are normalized, if path starts with ancestor + '/' it's within.
    return path.startswith(ancestor + '/')

