from .paths import normalize, join, is_within
from typing import Dict, Any

class FSError(Exception):
    """Base class for FileSystem errors."""
    pass

class NotFound(FSError):
    """Raised when a path is not found."""
    def __init__(self, path: str):
        # str(error) must be exactly one normalized absolute path
        super().__init__(normalize(path))
        self.path = normalize(path)

class AlreadyExists(FSError):
    """Raised when a path already exists and creation is not permitted (or for file conflicts)."""
    def __init__(self, path: str):
        super().__init__(normalize(path))
        self.path = normalize(path)

class NotADirectory(FSError):
    """Raised when an operation tries to access a file as a directory."""
    def __init__(self, path: str):
        super().__init__(normalize(path))
        self.path = normalize(path)

class IsADirectory(FSError):
    """Raised when an operation tries to treat a directory as a file for modification/reading."""
    def __init__(self, path: str):
        super().__init__(normalize(path))
        self.path = normalize(path)

class InvalidOperation(FSError):
    """Raised for invalid operations (e.g., operating on root, self-reference)."""
    def __init__(self, path: str):
        super().__init__(normalize(path))
        self.path = normalize(path)

class FileSystem:
    """In-memory filesystem implementation."""
    def __init__(self):
        # Structure: {path: {'type': 'file'/'dir', 'content': str | None}}
        self.data: Dict[str, Dict[str, Any]] = {}
        self.current_dir: str = '/'  # Always normalized
        # Initialize root directory
        self.data['/'] = {'type': 'dir', 'content': None}

    def _resolve_path(self, path: str) -> str: 
        """Resolves a potentially relative path against the current_dir and normalizes it."""
        if not path: return normalize(self.current_dir)

        # Use join to resolve path relative to CWD, then normalize
        # Note: join must handle path segments correctly based on rules.
        return normalize(join(self.current_dir, path))

    def _get_entry(self, path: str) -> Dict[str, Any]:
        """Retrieves an entry or raises NotFound if it doesn't exist."""
        if path not in self.data:
            raise NotFound(path)
        return self.data[path]

    def pwd(self) -> str:
        """Returns the current directory path."""
        return self.current_dir

    def cd(self, path: str) -> None:
        """Changes the current directory."""
        new_path = self._resolve_path(path)
        entry = self._get_entry(new_path)

        if entry['type'] != 'dir':
            # If it is a file, raise NotADirectory
            raise NotADirectory(new_path)

        self.current_dir = new_path

    def mkdir(self, path: str, parents: bool = False) -> None:
        """Creates a directory. If parents=True, creates missing parents."""
        target_path = self._resolve_path(path)

        if target_path == '/':
            raise InvalidOperation(target_path)

        # Check if target already exists
        if target_path in self.data:
            entry = self.data[target_path]
            if entry['type'] == 'file':
                # Existing file, raise AlreadyExists if parents=False
                if not parents:
                    raise AlreadyExists(target_path)
                # If parents=True and it's a file, we still reject the operation based on rule interpretation
                # Rule: existing directory is not an error (only if parents=True implies we can create it if it's missing).
                # The rule is: 'AlreadyExists(path) if it exists (with parents, only if it is a file)'
                raise AlreadyExists(target_path)
            # If it exists and is a directory, no error, and we do nothing.
            return

        if parents:
            # Complex logic for parents: need to walk up to find missing parents
            path_components = []
            remaining_path = target_path

            # Walk up until we hit root or an existing directory
            while remaining_path != '/' and remaining_path not in self.data:
                parent, name = split(remaining_path)
                if parent == remaining_path: # Safety break for root or issues
                    break
                path_components.append(remaining_path)
                remaining_path = parent

            # Traverse the path components in reverse (from deepest missing to shallowest missing)
            for component_path in reversed(path_components):
                parent_of_component, name = split(component_path)

                if parent_of_component not in self.data or self.data[parent_of_component]['type'] != 'dir':
                    # Create parent directory if it doesn't exist or isn't a directory
                    if parent_of_component not in self.data:
                        self.data[parent_of_component] = {'type': 'dir', 'content': None}
                    elif self.data[parent_of_component]['type'] == 'file':
                        # Conflict: Parent path is a file, cannot proceed
                        raise AlreadyExists(parent_of_component)

                # Now create the missing component directory
                if component_path not in self.data:
