            # Get direct children paths
            child_names = []
            for path_key in self.data:
                if path_key.startswith(current_path + '/') and path_key != current_path:
                    child_names.append(path_key)

            for child_path in child_names:
                child_name = split(child_path)[1]

                if fnmatch.fnmatchcase(child_name, pattern):
                    results.append(child_path)

                # Only traverse directories
                if self.data[child_path]['type'] == 'dir':
                    queue.append(child_path)

        return sorted(results)

    def exists(self, path: str) -> bool:
        return path in self.data

    def is_dir(self, path: str) -> bool:
        entry = self._get_entry(path)
        return entry['type'] == 'dir'

