import re
from decimal import Decimal, ROUND_HALF_UP, getcontext
from dataclasses import dataclass
from typing import List, Dict, Optional, Union, Any

# Set precision for Decimal calculations to handle percentages accurately
getcontext().prec = 30


def parse_amount(text: str) -> int:
    """Accepts digits optionally followed by '.' and one or two decimal places, 
    and returns cents (int). Raises ValueError for invalid input."""
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")

    # Regex matches: \d+ (integer), or \d*\.\d{1,2} (decimal)
    match = re.fullmatch(r"(\d+)|(\d*\.\d{1,2})", text)

    if not match:
        raise ValueError(f"Invalid amount format: {text}")

    if match.group(1):
        # Case 1: Integer input (e.g., '12')
        amount_str = match.group(1)
        amount_float = float(amount_str)
    else:
        # Case 2: Decimal input (e.g., '12.5' or '0.05')
        amount_str = match.group(2)
        amount_float = float(amount_str)

    # Convert to cents and round to nearest integer.
    cents = int(round(amount_float * 100))
    return cents

def format_amount(cents: int) -> str:
    """Returns the amount formatted to exactly two decimals with a leading '+' or '-' sign for negative values."""

    if cents == 0:
        return "+0.00"

    # Use Decimal for precise formatting to two places
    amount_decimal = Decimal(cents) / Decimal(100)

    # Format string ensures two decimal places
    formatted_str = f"{amount_decimal:.2f}"

    # Add explicit sign based on value
    if cents >= 0:
        return f"+{formatted_str}"
    else:
        # Decimal formatting already handles the negative sign, which is what we want.
        return formatted_str


@dataclass(frozen=True)
class Equal:
    members: Optional[List[str]] = None

@dataclass(frozen=True)
class Exact:
    shares: Dict[str, int]

@dataclass(frozen=True)
class Percent:
    shares: Dict[str, Any] # Shares are stored as string representations of percentages

@dataclass(frozen=True)
class Expense:
    description: str
    paid_by: str
    amount: int # amount is in cents
    split: Equal | Exact | Percent

# Helper functions for rounding logic

def _calculate_equal_shares(amount: int, group_members: List[str], split_members: Optional[List[str]]) -> Dict[str, int]:
    """Calculates shares for Equal split, handling remainder via alphabetical order."""
    if not split_members:
        split_members = group_members

    n = len(split_members)
    if n == 0:
        raise ValueError("Equal split requires at least one member.")

    base_share = amount // n
    remainder = amount % n

    shares: Dict[str, int] = {}

    # Calculate base shares
    for member in split_members:
        shares[member] = base_share

    # Distribute remainder based on alphabetical order
    remainder_distributers = sorted(split_members)
    for i in range(remainder):
        member = remainder_distributers[i]
        shares[member] += 1

    return shares


def _calculate_percent_shares(amount: int, group_members: List[str], percent_shares: Dict[str, Any]) -> Dict[str, int]:
    """Calculates shares for Percent split, handling rounding via largest fractional part."""
    total_percentage = 0
    for p_str in percent_shares.values():
        try:
            # Ensure all inputs are Decimal for calculation
            percentage = Decimal(str(p_str))
            total_percentage += percentage
        except Exception:
            raise ValueError(f"Invalid percentage value provided: {p_str}")

    if total_percentage != Decimal(100):
        raise ValueError(f"Percentages must sum up to exactly 100, but summed to {total_percentage}.")

    shares: Dict[str, int] = {}
    remainders: List[tuple[Decimal, str]] = []
    total_distributed = 0

    for member, p_str in percent_shares.items():
        try:
            percentage = Decimal(str(p_str))
        except Exception:
            raise ValueError(f"Invalid percentage value provided for {member}: {p_str}")

        # Calculate exact share value
        exact_share = (Decimal(amount) * percentage) / Decimal(100)

        # Floor calculation (the integer part)
        floor_share = int(exact_share.to_integral_value(rounding=ROUND_HALF_UP) if exact_share.is_zero() else exact_share.to_integral_value(rounding=ROUND_FLOOR))

        shares[member] = floor_share
        total_distributed += floor_share

        # Calculate fractional part for tie-breaking
        fractional_part = exact_share - Decimal(floor_share)
        remainders.append((fractional_part, member))

    missing = amount - total_distributed

    if missing > 0:
        # Sort by fractional part (descending), then by name (alphabetical ascending for ties)
        # We use negative fractional part for descending sort on the first element
        remainders.sort(key=lambda x: (-x[0], x[1]))

        # Distribute the remaining cents
        for i in range(missing):
            if i >= len(remainders):
                 # This should theoretically not happen if total_percentage == 100
                 raise RuntimeError("Not enough remainders to cover missing cents.")
            member = remainders[i][1]
            shares[member] += 1

    # Final validation check (should be guaranteed by logic above)
    if sum(shares.values()) != amount:
         raise RuntimeError(f"Internal share calculation error: Sum is {sum(shares.values())}, expected {amount}.")

    return shares


@dataclass
class Group:
    members: List[str]
    expenses: List[tuple[Expense, Dict[str, int]]] = None
    payments: List[tuple[str, str, int]] = None

    def __post_init__(self):
        # Ensure lists are initialized if not provided (important for mutable defaults)
        if self.expenses is None:
            self.expenses = []
        if self.payments is None:
            self.payments = []

    def add_member(self, name: str):
        if name in self.members:
            raise ValueError(f"Member {name} already in group.")
        self.members.append(name)

    def add_expense(self, expense: Expense) -> Dict[str, int]:
        if expense.amount <= 0:
            raise ValueError("Expense amount must be positive.")

        # 1. Validate Payer
        if expense.paid_by not in self.members:
            raise ValueError(f"Payer '{expense.paid_by}' is not a member of the group.")

        shares: Dict[str, int]

        # 2. Calculate Shares based on split type
        split = expense.split

        if isinstance(split, Equal):
            if split.members is not None and not all(m in self.members for m in split.members):
                 raise ValueError("Members specified in Equal split are not all in the group.")
            shares = _calculate_equal_shares(expense.amount, self.members, split.members)

        elif isinstance(split, Exact):
            for member, share_str in split.shares.items():
                try:
                    share = int(parse_amount(str(share_str)))
                except ValueError:
                    raise ValueError(f"Invalid share amount '{share_str}' for member {member}.")

                if share < 0:
                    raise ValueError(f"Share for {member} cannot be negative.")

                if member not in self.members:
                    raise ValueError(f"Participant '{member}' in Exact split is not in the group.")

                shares[member] = share

            if sum(shares.values()) != expense.amount:
                raise ValueError(f"Exact shares do not sum up to the total amount ({sum(shares.values())} != {expense.amount}).")

        elif isinstance(split, Percent):
            if not all(m in self.members for m in split.shares):
                 raise ValueError("Participants in Percent split are not all in the group.")
            shares = _calculate_percent_shares(expense.amount, self.members, split.shares)

        else:
            raise TypeError("Unknown split type encountered.")

        # 3. Store expense and return shares in member order
        # The spec requires shares dictionary keyed by member, but the return must reflect group member order.
        # We return the dict, and the caller (or internal logic) must ensure order if needed, 
        # but the requirement is that the internal storage uses the member order for shares.

        # For internal storage consistency (as per spec: 'with one key per participant, in the group's member order'), 
        # we create an ordered structure for storage, although returning a dict is standard for shares.
        # We return the calculated dict, as requested for the return type.

        self.expenses.append((expense, shares))
        return shares

    def add_payment(self, payer: str, payee: str, amount: int):
        if payer not in self.members or payee not in self.members:
            raise ValueError("Payer or payee not in group members.")
        if amount <= 0:
             raise ValueError("Payment amount must be positive.")

        self.payments.append((payer, payee, amount))


def load_group(data: Dict) -> Group:
